/** All translations for zizhitongjian ch.053 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑 第053卷", literal: "Zizhi Tongjian, Volume 53.", idiomatic: "Zizhi Tongjian, Volume 53." },
  { zh: "【漢紀四十五】　起柔兆閹茂，盡柔兆涒灘，凡十一年。", literal: "【Han Records 45】 From Rouzhao Yanmao through Rouzhao Tuantan—in all, eleven years.", idiomatic: "【Han Records 45】 From the first year of the Rouzhao cycle through the last year of the Rouzhao cycle—eleven years in all." },
  { zh: "夏，四月，庚辰，令郡、國舉明經詣太學，自大將軍以下皆遣子受業；", literal: "In summer, the fourth month, on the day gengchen, an order that commanderies and kingdoms recommend those versed in the classics to proceed to the Imperial Academy; from the Grand General down, all were to send sons to receive instruction;", idiomatic: "In summer, in the fourth month, on gengchen day, an edict ordered commanderies and kingdoms to recommend men versed in the classics to the Imperial Academy; from the Grand General down, all were to send their sons to study;" },
  { zh: "歲滿課試，拜官有差。", literal: "when the year was complete they were examined and tested, and offices were conferred with distinctions.", idiomatic: "after a year's study they were examined and appointed to office according to merit." },
  { zh: "又千石、六百石、四府掾屬、三署郎、四姓小侯先能通經者，各令隨家法，其高第者上名牒，當以次賞進。", literal: "Again, those among the thousand- and six-hundred-bushel officials, the four offices' clerical subordinates, the three bureaus' gentlemen, and the four-surname minor marquises who already could master the classics were each ordered to follow their household's tradition; those of high rank were to submit name registers and should be rewarded and advanced in order.", idiomatic: "Officials of thousand- and six-hundred-bushel rank, clerks of the four offices, gentlemen of the three bureaus, and minor marquises of the four surnames who already knew the classics were each to follow their household tradition; those of highest rank were to submit name registers for reward and advancement in due order." },
  { zh: "自是遊學增盛，至三萬餘生。", literal: "From this roaming study increased and flourished, reaching more than thirty thousand students.", idiomatic: "From this scholarly study flourished, until there were more than thirty thousand students." },
  { zh: "五月，庚寅，徙樂安王鴻為渤海王。", literal: "In the fifth month, on the day gengyin, Prince of Le'an Hong was moved to be Prince of Bohai.", idiomatic: "In the fifth month, on gengyin day, Prince of Le'an Hong was transferred to be Prince of Bohai." },
  { zh: "海水溢，漂沒民居。", literal: "Seawater overflowed and drifted away and drowned people's dwellings.", idiomatic: "The sea overflowed and swept away dwellings." },
  { zh: "六月，丁巳，赦天下。", literal: "In the sixth month, on the day dingsi, the realm was pardoned.", idiomatic: "In the sixth month, on dingsi day, the realm was pardoned." },
  { zh: "帝少而聰慧，嘗因朝會，目梁冀曰：「此跋扈將軍也！", literal: "The emperor from youth was clever and keen. Once during a court assembly he fixed his eyes on Liang Ji and said, \"This is the overbearing general!\"", idiomatic: "The emperor had been clever from youth. Once at court he fixed his eyes on Liang Ji and said, \"There is the overbearing general!\"" },
  { zh: "」冀聞，深惡之。", literal: "\" Ji heard and deeply hated him.", idiomatic: "\" Ji heard of it and hated him deeply." },
  { zh: "閏月，甲申，冀使左右置毒於煮餅以進之。", literal: "In the intercalary month, on the day jiashen, Ji had his attendants place poison in boiled cakes to present them.", idiomatic: "In the intercalary month, on jiashen day, Ji had his attendants put poison in boiled cakes and present them." },
  { zh: "帝若煩甚，使促召太尉李固。", literal: "The emperor grew very distressed and had someone urgently summon Grand Commandant Li Gu.", idiomatic: "The emperor grew very ill and urgently summoned Grand Commandant Li Gu." },
  { zh: "固入前，問帝得患所由；", literal: "Gu entered and advanced, asking the emperor the source of his illness;", idiomatic: "Gu came forward and asked how the emperor had fallen ill;" },
  { zh: "帝尚能言，曰：「食煮餅。", literal: "the emperor could still speak and said, \"I ate boiled cakes.", idiomatic: "the emperor could still speak and said, \"I ate boiled cakes." },
  { zh: "今腹中悶，得水尚可活。", literal: "Now my belly is oppressed; if I get water I may still live.\"", idiomatic: "My belly is tight; if I get water I may still live.\"" },
  { zh: "」時冀亦在側，曰：「恐吐，不可飲水。", literal: "\" At the time Ji was also at his side and said, \"I fear vomiting—you must not drink water.", idiomatic: "\" Ji was also at his side and said, \"You may vomit—you must not drink water." },
  { zh: "」語未絕而崩。", literal: "\" Before the words were finished he collapsed and died.", idiomatic: "\" Before he finished speaking, the emperor died." },
  { zh: "固伏屍號哭，推舉侍醫。", literal: "Gu prostrated himself on the corpse and wailed, pushing forward and presenting the attending physicians.", idiomatic: "Gu threw himself on the corpse and wailed, thrusting the attending physicians forward." },
  { zh: "冀慮其事洩，大惡之。", literal: "Ji feared the matter would leak out and hated him greatly.", idiomatic: "Ji feared the affair would leak out and hated him bitterly." },
  { zh: "將議立嗣，固與司徒胡廣、司空趙戒先與冀書曰：「天下不幸，頻年之間，國祚三絕。", literal: "When they were about to deliberate on establishing an heir, Gu together with Minister of Education Hu Guang and Minister of Works Zhao Jie first sent Ji a letter, saying, \"The realm is unfortunate—in the space of a few years the imperial line has thrice been cut off.", idiomatic: "As they were about to choose an heir, Gu together with Minister of Education Hu Guang and Minister of Works Zhao Jie first wrote Ji, saying, \"The realm is unfortunate—in a few short years the imperial line has been cut off three times." },
  { zh: "今當立帝，天下重器，誠知太后垂心，將軍勞慮，詳擇其人，務存聖明。", literal: "\"Now an emperor must be established—the realm's weighty vessel. Your servants truly know the empress dowager bends her heart and the general labors in thought, carefully choosing the man and striving to preserve sagely clarity.", idiomatic: "\"Now we must establish an emperor—the weighty vessel of the realm. We know the empress dowager bends her heart to this and the general labors in thought, carefully choosing a man of sagely clarity." },
  { zh: "然愚情眷眷，竊獨有懷。", literal: "\"Yet your servants' foolish feelings are attached and clinging; we privately each have our thoughts.", idiomatic: "\"Yet we are deeply concerned and each hold private thoughts." },
  { zh: "遠尋先世廢立舊儀，近見國家踐祚前事，未嘗不詢訪公卿，廣求群議，令上應天心，下合眾望。", literal: "\"Seeking far the former age's statutes on deposing and establishing, and seeing near the state's affairs before taking the throne, never have they failed to inquire of the ducal ministers and broadly seek the multitude's counsel, making what is above answer Heaven's heart and what is below accord with the multitude's hope.", idiomatic: "\"Looking back to former statutes on deposing and establishing rulers, and at recent precedents when the throne changed hands, never did they fail to consult the ministers and seek broad counsel, so that Heaven's will was answered above and the people's hopes below." },
  { zh: "《傳》曰：『以天下與人易，為天下得人難。", literal: "\"The Commentary says: 'To give the realm to another is easy; to obtain the right man for the realm is hard.", idiomatic: "\"The Commentary says: 'To give away the realm is easy; to find the right man for the realm is hard." },
  { zh: "』昔昌邑之立，昏亂日滋；", literal: "\"'Of old when Changyi was established, confusion and disorder daily increased;", idiomatic: "\"'When Changyi was made emperor, confusion daily deepened;" },
  { zh: "霍光憂愧發憤，悔之折骨。", literal: "Huo Guang, in worry, shame, and rising anger, regretted it until his bones might break.", idiomatic: "Huo Guang, in shame and fury, regretted it to the bone." },
  { zh: "自非博陸忠勇，延年奮發，大漢之祀，幾將傾矣。", literal: "\"If not for Marquis of Bolu's loyalty and courage and Yan Nian's rising effort, the Great Han's sacrifices would nearly have toppled.", idiomatic: "\"Had not the Marquis of Bolu been loyal and brave and Yan Nian risen in his defense, the sacrifices of the Great Han would nearly have fallen." },
  { zh: "至憂至重，可不熟慮！", literal: "\"The utmost worry, the utmost weight—how can one not deliberate thoroughly!\"", idiomatic: "\"This is the gravest of matters—how can we not deliberate with utmost care!\"" },
  { zh: "悠悠萬事，唯此為大；", literal: "\"Of the vast myriad affairs, only this is greatest;", idiomatic: "\"Of ten thousand affairs, none is greater than this;" },
  { zh: "國之興衰，在此一舉。", literal: "the state's rise and fall hang on this one act.\"", idiomatic: "the state's rise and fall hang on this one choice.\"" },
  { zh: "」冀得書，乃召三公、中二千石、列侯，大議所立。", literal: "\" Ji received the letter and thereupon summoned the Three Excellencies, the two-thousand-bushel officials, and the ranked marquises for great deliberation on whom to establish.", idiomatic: "\" Ji received the letter and summoned the Three Excellencies, officials of two-thousand-bushel rank, and marquises to debate the succession." },
  { zh: "固、廣、戒及大鴻臚杜喬皆以為清河王蒜明德著聞，又屬最尊親，宜立為嗣，朝臣莫不歸心。", literal: "Gu, Guang, Jie, and Grand Herald Du Qiao all thought Prince of Qinghe Suan's bright virtue was renowned, and moreover he was of the most honored kinship—he should be established as heir; the court ministers none failed to turn their hearts to him.", idiomatic: "Gu, Guang, Jie, and Grand Herald Du Qiao all held that Prince of Qinghe Suan's bright virtue was well known and that he was of the most honored kinship—he should be made heir, and the court ministers all favored him." },
  { zh: "而中常侍曹騰嘗謁蒜，蒜不為禮，宦者由此惡之。", literal: "But Regular Palace Attendant Cao Teng had once called on Suan; Suan did not show him courtesy, and the eunuchs from this hated him.", idiomatic: "But Regular Palace Attendant Cao Teng had once called on Suan, and Suan did not treat him with courtesy; the eunuchs therefore hated him." },
  { zh: "初，平原王冀既貶歸河間，其父請分蠡吾縣以侯之；", literal: "Earlier, when Prince of Pingyuan Ji had been demoted and returned to Hejian, his father requested to divide Liwu county to ennoble him as marquis;", idiomatic: "Earlier, when Prince of Pingyuan Ji was demoted and returned to Hejian, his father asked that Liwu county be split off to ennoble him;" },
  { zh: "順帝許之。", literal: "Emperor Shun permitted it.", idiomatic: "Emperor Shun granted it." },
  { zh: "翼卒，子志嗣；", literal: "Ji died; his son Zhi succeeded;", idiomatic: "Ji died and his son Zhi succeeded;" },
  { zh: "梁太后欲以女弟妻志，征到夏門亭。", literal: "the Empress Dowager Liang wished to marry her younger sister to Zhi and summoned him to Xiamen Pavilion.", idiomatic: "the Empress Dowager Liang wished to marry her younger sister to Zhi and summoned him to Xiamen Pavilion." },
  { zh: "會帝崩，梁冀欲立志。", literal: "It happened that the emperor died; Liang Ji wished to establish Zhi.", idiomatic: "When the emperor died, Liang Ji wished to establish Zhi." },
  { zh: "眾論既異，憤憤不得意，而未有以相奪。", literal: "The multitude's counsel had already differed; he was angry and displeased, yet had no means to wrest the choice away.", idiomatic: "Public opinion had already turned elsewhere; he was furious and thwarted, yet had no way to seize the choice." },
  { zh: "曹騰等聞之，夜往說冀曰：「將軍累世有椒房之親，東攝萬機，賓客縱橫，多有過差。", literal: "Cao Teng and the rest heard and by night went to persuade Ji, saying, \"General, for generations your house has had empress-dowager kinship; you hold the myriad affairs in the east, and your clients roam freely—many have faults and errors.", idiomatic: "Cao Teng and the others heard of it and went by night to persuade Ji, saying, \"General, for generations your house has been tied to the throne; you hold the reins of government, and your clients run freely—many have transgressed." },
  { zh: "清河王嚴明，若果立，則將軍受禍不久矣！", literal: "\"Prince of Qinghe is stern and clear; if he is truly established, then the general will suffer disaster before long!\"", idiomatic: "\"Prince of Qinghe is stern and upright; if he is enthroned, you will suffer disaster before long!\"" },
  { zh: "不如立蠡吾侯，富貴可長保也。", literal: "\"Better to establish Marquis of Liwu—wealth and honor can be long preserved.\"", idiomatic: "\"Better to establish the Marquis of Liwu—then wealth and honor can be preserved for long.\"" },
  { zh: "」冀然其言，明日，重會公卿，冀意氣凶凶，言辭激切，自胡廣、趙戒以下莫不懾憚，皆曰：「惟大將軍令！", literal: "\" Ji approved their words. The next day he reconvened the ducal ministers. Ji's spirit was fierce and violent, his words sharp and urgent; from Hu Guang and Zhao Jie down none failed to fear and dread, and all said, \"Only the Grand General's command!\"", idiomatic: "\" Ji approved their counsel. The next day he reconvened the ministers. Ji's manner was fierce and his words cutting; from Hu Guang and Zhao Jie down all were terrified and said, \"Only the Grand General's command!\"" },
  { zh: "」獨李固、杜喬堅守本議。", literal: "\" Only Li Gu and Du Qiao firmly held to their original counsel.", idiomatic: "\" Only Li Gu and Du Qiao held firm to their original position." },
  { zh: "冀厲聲曰：「罷會！", literal: "Ji shouted harshly, \"Dismiss the assembly!\"", idiomatic: "Ji shouted, \"The meeting is adjourned!\"" },
  { zh: "」固猶望眾心可立，復以書勸冀，冀愈激怒。", literal: "\" Gu still hoped the multitude's hearts could establish Suan and again with a letter urged Ji; Ji grew ever more enraged.", idiomatic: "\" Gu still hoped public opinion could prevail and again wrote to urge Ji; Ji grew only more furious." },
  { zh: "丁亥，冀說太后，先策免固。", literal: "On the day dinghai, Ji persuaded the empress dowager and first by written order dismissed Gu.", idiomatic: "On dinghai day Ji persuaded the empress dowager to dismiss Gu by edict." },
  { zh: "戊子，以司徒胡廣為太尉；", literal: "On the day wuzi, Minister of Education Hu Guang was made Grand Commandant;", idiomatic: "On wuzi day Minister of Education Hu Guang was made Grand Commandant;" },
  { zh: "司空趙戒為司徒，與大將軍冀參錄尚書事；", literal: "Minister of Works Zhao Jie was made Minister of Education and with Grand General Ji jointly oversaw the Masters of Writing;", idiomatic: "Minister of Works Zhao Jie was made Minister of Education and with Grand General Ji jointly oversaw the Masters of Writing;" },
  { zh: "太僕袁湯為司空。", literal: "Grand Steward Yuan Tang was made Minister of Works.", idiomatic: "Grand Steward Yuan Tang was made Minister of Works." },
  { zh: "湯，安之孫也。", literal: "Tang was the grandson of An.", idiomatic: "Tang was the grandson of An." },
  { zh: "庚寅，使大將軍冀持節以王青蓋車迎蠡吾侯志入南宮；", literal: "On the day gengyin, the Grand General Ji was sent with credentials and the king's blue-canopied carriage to welcome Marquis of Liwu Zhi into the Southern Palace;", idiomatic: "On gengyin day Grand General Ji was sent with credentials and the royal carriage to welcome Marquis of Liwu Zhi into the Southern Palace;" },
  { zh: "其日，即皇帝位，時年十五。", literal: "that same day he immediately took the emperor's throne; he was fifteen years old.", idiomatic: "that same day he took the throne; he was fifteen years old." },
  { zh: "太后猶臨朝政。", literal: "The empress dowager still presided over court government.", idiomatic: "The empress dowager still held court." },
  { zh: "秋，七月，乙卯，葬孝質皇帝於靜陵。", literal: "In autumn, the seventh month, on the day yimao, Emperor Xiaozhi was buried at Jing Mausoleum.", idiomatic: "In autumn, in the seventh month, on yimao day, Emperor Xiaozhi was buried at Jing Mausoleum." },
  { zh: "大將軍掾朱穆奏記勸戒梁冀曰：「明年丁亥之歲，刑德合於乾位，《易經》龍戰之會，陽道將勝，陰道將負。", literal: "Grand General's clerk Zhu Mu submitted a note urging and admonishing Liang Ji, saying, \"In the coming year, the year dinghai, punishment and virtue unite at the Qian position—the Changes' meeting of dragons in battle; the yang Way will prevail, the yin Way will be overborne.", idiomatic: "Grand General's clerk Zhu Mu submitted a note admonishing Liang Ji, saying, \"In the coming year, dinghai, punishment and virtue unite at the Qian position—the Changes' meeting of dragons in battle; the yang Way will prevail and the yin Way will fail." },
  { zh: "願將軍專心公朝，割除私慾，廣求賢能，斥遠佞惡，為皇帝置師傅，得小心忠篤敦禮之士，將軍與之俱入，參勸講援，師賢法古，此猶倚南山、坐平原也，誰能傾之！", literal: "\"Your servant wishes the general to focus his heart on the public court, cut away private desires, broadly seek the worthy and able, drive far the sycophantic and wicked, and for the emperor appoint a tutor—obtaining men careful, loyal, sincere, and honoring ritual. The general should enter with them, jointly counsel, lecture, and support, taking worthy teachers and modeling antiquity. This is like leaning on the southern mountain or sitting on a plain—who can overturn it!\"", idiomatic: "\"May the general devote himself to the public court, cut away private desire, seek the worthy broadly, drive off the sycophantic and wicked, and appoint for the emperor a tutor—men careful, loyal, sincere, and steeped in ritual. Enter with them, counsel and instruct together, take worthy teachers and model antiquity. That is like leaning on the southern mountain or sitting on level ground—who can overturn you!\"" },
  { zh: "議郎大夫之位，本以式序儒術高行之士，今多非其人，九卿之中亦有乖其任者，惟將軍察焉！", literal: "\"The posts of Gentleman Consultant and Grandee were originally to arrange in order men of Confucian learning and lofty conduct; now many are not such men. Among the Nine Ministers too there are some who fail their charge—only may the general examine this!\"", idiomatic: "\"The posts of Gentleman Consultant and Grandee were meant to rank men of learning and lofty conduct; now many unfit men hold them, and among the Nine Ministers some fail their charge—may the general examine this!\"" },
  { zh: "」又薦種暠、欒巴等，冀不能用。", literal: "\" He also recommended Zhong Gao, Luan Ba, and others; Ji could not employ them.", idiomatic: "\" He also recommended Zhong Gao, Luan Ba, and others; Ji did not act on them." },
  { zh: "穆，暉之孫也。", literal: "Mu was the grandson of Hui.", idiomatic: "Mu was the grandson of Hui." },
  { zh: "九月，戊戌，追尊河間孝王為孝穆皇，夫人趙氏曰孝穆後，廟曰清廟，陵曰樂成陵；", literal: "In the ninth month, on the day wuxu, posthumous honor was given to Prince Xiaoxiao of Hejian as Emperor Xiaomu, Lady Zhao as Empress Xiaomu; the temple was called Qing Temple, the tomb Lecheng Mausoleum;", idiomatic: "In the ninth month, on wuxu day, Prince Xiaoxiao of Hejian was posthumously honored as Emperor Xiaomu, Lady Zhao as Empress Xiaomu; the temple was named Qing Temple and the tomb Lecheng Mausoleum;" },
  { zh: "蠡吾先侯曰孝崇皇，廟曰烈廟，陵曰博陵；", literal: "the former Marquis of Liwu was called Emperor Xiaochong; the temple Lie Temple, the tomb Boling;", idiomatic: "the former Marquis of Liwu was honored as Emperor Xiaochong; the temple Lie Temple and the tomb Boling;" },
  { zh: "皆置令、丞、使司徒持節奉策書璽綬，祠以太牢。", literal: "for all, directors and assistants were appointed; the Minister of Education was sent with credentials to present credential books, seals, and cords, and sacrifice with the great victim.", idiomatic: "for each, directors and assistants were appointed; the Minister of Education was sent with credentials to present patent scrolls, seals, and cords, and sacrifice with the great victim." },
  { zh: "冬，十月，甲午，尊帝母匽氏為博園貴人。", literal: "In winter, the tenth month, on the day jiawu, the emperor's mother, the Yan clan, was honored as Lady of the Garden of Bo.", idiomatic: "In winter, in the tenth month, on jiawu day, the emperor's mother, Lady Yan, was honored as Lady of the Garden of Bo." },
  { zh: "滕撫性方直，不交權勢，為宦官所惡；", literal: "Teng Fu's nature was square and upright; he did not associate with power-holders and was hated by the eunuchs;", idiomatic: "Teng Fu was upright by nature and did not court the powerful; the eunuchs hated him;" },
  { zh: "論討賊功當封，太尉胡廣承旨奏黜之；", literal: "when his merit in discussing and attacking bandits was judged worthy of enfeoffment, Grand Commandant Hu Guang, following the imperial intent, memorialized to dismiss him;", idiomatic: "when his merit in suppressing bandits was judged worthy of enfeoffment, Grand Commandant Hu Guang, following the court's intent, memorialized to have him dismissed;" },
  { zh: "卒於家。", literal: "he died at home.", idiomatic: "he died at home." },
  { zh: "孝桓皇帝上之上", literal: "Emperor Xiaohuan, First Part, Upper.", idiomatic: "Emperor Huan — Part One, Upper." },
  { zh: "春，正月，辛亥朔，日有食之。", literal: "In spring, the first month, on the new moon of the day xinhai, the sun was eclipsed.", idiomatic: "In spring, in the first month, on the new moon of xinhai day, there was a solar eclipse." },
  { zh: "戊午，赦天下。", literal: "On the day wuwu, the realm was pardoned.", idiomatic: "On wuwu day the realm was pardoned." },
  { zh: "三月，龍見譙。", literal: "In the third month, a dragon appeared at Qiao.", idiomatic: "In the third month a dragon was seen at Qiao." },
  { zh: "夏，四月，庚寅，京師地震。", literal: "In summer, the fourth month, on the day gengyin, the capital had an earthquake.", idiomatic: "In summer, in the fourth month, on gengyin day the capital suffered an earthquake." },
  { zh: "立阜陵王代兄勃遒亭侯便為阜陵王。", literal: "Prince of Fuling Wang Dai's elder brother, Marquis of Boqiu Bian, was established as Prince of Fuling.", idiomatic: "Marquis of Boqiu Bian, elder brother of Prince of Fuling Wang Dai, was made Prince of Fuling." },
  { zh: "六月，太尉胡廣罷。", literal: "In the sixth month, Grand Commandant Hu Guang was dismissed.", idiomatic: "In the sixth month Grand Commandant Hu Guang was dismissed." },
  { zh: "光祿勳杜喬為太尉。", literal: "Director of the Imperial Clan Du Qiao was made Grand Commandant.", idiomatic: "Director of the Imperial Clan Du Qiao was made Grand Commandant." },
  { zh: "自李固之廢，內外喪氣，群臣側足而立，唯喬正色無所回橈，由是朝野皆倚望焉。", literal: "From Li Gu's dismissal, within and without spirits were lost; the host of ministers stood on tiptoe to the side—only Qiao kept his proper color and bent nowhere. From this court and countryside all leaned their hopes on him.", idiomatic: "Since Li Gu's dismissal, court and countryside had lost heart; ministers walked on eggshells—only Qiao stood upright and unbending, and from this court and countryside alike pinned their hopes on him." },
  { zh: "秋，七月，渤海孝王鴻薨，無子；", literal: "In autumn, the seventh month, Prince Xiaoxiao of Bohai Hong died; he had no son;", idiomatic: "In autumn, in the seventh month, Prince Xiaoxiao of Bohai Hong died without an heir;" },
  { zh: "太后立帝弟蠡吾侯悝為渤海王，以奉鴻祀。", literal: "the empress dowager established the emperor's younger brother, Marquis of Liwu Kui, as Prince of Bohai to maintain Hong's sacrifices.", idiomatic: "the empress dowager made the emperor's younger brother, Marquis of Liwu Kui, Prince of Bohai to maintain Hong's sacrifices." },
  { zh: "詔以定策功，益封梁冀萬三千戶，封冀弟不疑為穎陽侯，蒙為西平侯，冀子胤為襄邑侯，胡廣為安樂侯，趙戒為廚亭侯，袁湯為安國侯。", literal: "An edict, for merit in fixing the succession, added to Liang Ji's fief thirteen thousand households; Ji's younger brother Buyi was enfeoffed as Marquis of Yingyang, Meng as Marquis of Xiping, Ji's son Yin as Marquis of Xiangyi, Hu Guang as Marquis of Anle, Zhao Jie as Marquis of Chuting, Yuan Tang as Marquis of Anguo.", idiomatic: "An edict, for merit in fixing the succession, added thirteen thousand households to Liang Ji's fief; Ji's younger brother Buyi was made Marquis of Yingyang, Meng Marquis of Xiping, Ji's son Yin Marquis of Xiangyi, Hu Guang Marquis of Anle, Zhao Jie Marquis of Chuting, and Yuan Tang Marquis of Anguo." },
  { zh: "又封中常侍劉廣等皆為列侯。", literal: "Again, Regular Palace Attendants Liu Guang and the rest were all enfeoffed as ranked marquises.", idiomatic: "Regular Palace Attendants Liu Guang and others were also enfeoffed as marquises." },
  { zh: "杜喬諫曰：「古之明君，皆以用賢、賞罰為務。", literal: "Du Qiao remonstrated, saying, \"The enlightened rulers of antiquity all took employing the worthy and rewards and punishments as their task.", idiomatic: "Du Qiao remonstrated, saying, \"Enlightened rulers of antiquity made employing the worthy and dispensing rewards and punishments their chief task." },
  { zh: "失國之主，其朝豈無貞干之臣，典誥之篇哉？", literal: "\"Do the rulers who lost their states lack in their courts loyal and upright ministers, or the chapters of the ordinances and announcements?\"", idiomatic: "\"Did rulers who lost their states lack loyal ministers in court, or the chapters of the ordinances and announcements?\"" },
  { zh: "患得賢不用其謀，韜書不施其教，聞善不信其義，聽讒不審其理也。", literal: "\"The trouble is that when they obtain the worthy they do not use their plans, that they hide books and do not apply their teaching, that hearing good they do not trust its meaning, and that hearing slander they do not examine its reason.\"", idiomatic: "\"The trouble is that when they find worthy men they do not heed their counsel, that they shelve the classics and do not apply their teaching, that hearing good they do not trust it, and that hearing slander they do not weigh its truth.\"" },
  { zh: "陛下自籓臣即位，天人屬心，不急忠賢之禮而先左右之封，梁氏一門，宦者微孽，並帶無功之紱，裂勞臣之土，其為乖濫，胡可勝言！", literal: "\"Your Majesty, from a feudatory subject taking the throne, Heaven and men turned their hearts to you—yet you do not hurry the rites toward the loyal and worthy but first enfeoff those at your side. The whole Liang house, eunuchs and petty spawn, all wear sashes of meritless reward and split the lands of toiling ministers. How excessive the violation—how can it all be told!\"", idiomatic: "\"Your Majesty rose from a feudatory post when Heaven and men turned their hearts to you—yet you do not hurry to honor the loyal and worthy but first enfeoff those at your side. The whole Liang clan, eunuchs and petty creatures, all wear ribbons they did not earn and carve up the lands of ministers who labored for the state. How excessive the abuse—words cannot compass it!\"" },
  { zh: "夫有功不賞，為善失其望；", literal: "\"When merit goes unrewarded, those who do good lose their hope;", idiomatic: "\"When merit goes unrewarded, the good lose hope;" },
  { zh: "奸回不詰，為惡肆其凶。", literal: "when the wicked and rebellious are not prosecuted, those who do evil unleash their violence.\"", idiomatic: "when the wicked go unpunished, evildoers unleash their violence.\"" },
  { zh: "故陳資斧而人靡畏，班爵位而物無勸。", literal: "\"Therefore though axes are displayed, men have no fear; though noble ranks are distributed, things have no encouragement.\"", idiomatic: "\"Therefore though axes of punishment are displayed, none fear; though noble ranks are handed out, none are moved to strive.\"" },
  { zh: "苟遂斯道，豈伊傷政為亂而已，喪身亡國，可不慎哉！", literal: "\"If this course is followed, is it only that government is harmed and disorder made? Loss of life and loss of state—how can one not be careful!\"", idiomatic: "\"If this course is followed, it is not only government harmed and disorder bred—you will lose your life and your state. Can you not be careful!\"" },
  { zh: "」書奏，不省。", literal: "\" The memorial was submitted; it was not heeded.", idiomatic: "\" The memorial was submitted; the emperor took no notice." },
  { zh: "八月，乙未，立皇后梁氏。", literal: "In the eighth month, on the day yiwei, Empress Liang was established.", idiomatic: "In the eighth month, on yiwei day, Empress Liang was installed." },
  { zh: "梁冀欲以厚禮迎之，杜喬據執舊典不聽。", literal: "Liang Ji wished to welcome her with heavy ceremony; Du Qiao held to the old statutes and would not permit it.", idiomatic: "Liang Ji wished to welcome her with lavish ceremony; Du Qiao held to the old statutes and refused." },
  { zh: "冀屬喬舉汜宮為尚書，喬以宮為臧罪，不用。", literal: "Ji entrusted Qiao to recommend Si Gong as Master of Writing; Qiao, because Gong had a theft crime, did not employ him.", idiomatic: "Ji asked Qiao to recommend Si Gong for Master of Writing; Qiao, because Gong had been convicted of theft, refused." },
  { zh: "由是日忤於冀。", literal: "From this he daily clashed with Ji.", idiomatic: "From this he daily clashed with Ji." },
  { zh: "九月，丁卯，京師地震。", literal: "In the ninth month, on the day dingmao, the capital had an earthquake.", idiomatic: "In the ninth month, on dingmao day, the capital suffered an earthquake." },
  { zh: "喬以災異策免。", literal: "Qiao was dismissed by written order on account of prodigies and disasters.", idiomatic: "Qiao was dismissed by edict on account of omens and earthquakes." },
  { zh: "冬，十月，以司徒趙戒為太尉，司空袁湯為司徒，前太尉胡廣為司空。", literal: "In winter, the tenth month, Minister of Education Zhao Jie was made Grand Commandant, Minister of Works Yuan Tang was made Minister of Education, and the former Grand Commandant Hu Guang was made Minister of Works.", idiomatic: "In winter, in the tenth month, Minister of Education Zhao Jie was made Grand Commandant, Minister of Works Yuan Tang Minister of Education, and former Grand Commandant Hu Guang Minister of Works." },
  { zh: "宦者唐衡、左心官共譖杜喬於帝曰：「陛下前當即位，喬與李固抗議，以為不堪奉漢宗祀。", literal: "The eunuchs Tang Heng and Left Heart Attendant together slandered Du Qiao to the emperor, saying, \"When Your Majesty was about to take the throne, Qiao with Li Gu resisted in counsel, holding that you were unfit to maintain the Han clan's sacrifices.\"", idiomatic: "The eunuchs Tang Heng and Left Heart Attendant together slandered Du Qiao to the emperor, saying, \"When Your Majesty was about to take the throne, Qiao with Li Gu resisted in counsel, holding that you were unfit to maintain the Han sacrifices.\"" },
  { zh: "」帝亦怨之。", literal: "\" The emperor also resented him.", idiomatic: "\" The emperor also resented him." },
  { zh: "十一月，清河劉文與南郡妖賊劉鮪交通，妄言：清河王當統天下，欲共立蒜。", literal: "In the eleventh month, Liu Wen of Qinghe communicated with the sorcerer-bandit Liu Wei of Nan commandery, speaking wildly that the Prince of Qinghe should rule all under Heaven; they wished jointly to establish Suan.", idiomatic: "In the eleventh month Liu Wen of Qinghe conspired with the sorcerer-bandit Liu Wei of Nan commandery, claiming wildly that Prince of Qinghe should rule the realm, and sought jointly to enthrone Suan." },
  { zh: "事覺，文等遂劫清河相謝暠曰：「當立王為天子，以暠為公。", literal: "When the affair came to light, Wen and the rest then seized the Chancellor of Qinghe, Xie Hao, and said, \"We ought to install the prince as Son of Heaven and make Hao a duke.", idiomatic: "When the plot was discovered, Wen and his followers seized the Chancellor of Qinghe, Xie Hao, and said, \"We ought to install the prince as Son of Heaven and make Hao a duke.\"" },
  { zh: "」暠罵之，文刺殺暠。", literal: "\" Hao cursed them; Wen stabbed and killed Hao.", idiomatic: "\" Hao cursed them, and Wen stabbed and killed him." },
  { zh: "於是捕文、鮪，誅之。", literal: "Thereupon Wen and Yu were arrested and executed.", idiomatic: "Thereupon Wen and Yu were arrested and executed." },
  { zh: "有司劾奏蒜；", literal: "The responsible offices impeached and memorialized against Su;", idiomatic: "The responsible offices impeached Liu Su;" },
  { zh: "坐貶爵為尉氏侯，徙桂陽，自殺。", literal: "for the offense his noble rank was reduced to Marquis of Weishi, he was moved to Guiyang, and killed himself.", idiomatic: "For the offense his rank was reduced to Marquis of Weishi, he was moved to Guiyang, and killed himself." },
  { zh: "梁冀因誣李固、杜喬，雲與文、鮪等交通，請逮按罪；", literal: "Liang Ji thereupon falsely accused Li Gu and Du Qiao, saying they had dealings with Wen, Yu, and the rest, and requested arrest and investigation by crime;", idiomatic: "Liang Ji thereupon falsely accused Li Gu and Du Qiao of colluding with Wen, Yu, and the rest, and asked that they be arrested and prosecuted;" },
  { zh: "太后素知喬忠，不許。", literal: "the Empress Dowager had long known Qiao to be loyal and did not consent.", idiomatic: "the Empress Dowager had long known Qiao to be loyal and would not consent." },
  { zh: "冀遂收固下獄；", literal: "Ji thereupon seized Gu and put him in prison;", idiomatic: "Ji thereupon seized Gu and imprisoned him;" },
  { zh: "門生渤海王調貫械上書，證固之枉，河內趙承等數十人亦要鈇鍎詣闕通訴；", literal: "his student Wang Diao of Bohai wore cangues and submitted a memorial proving Gu's injustice; Zhao Cheng of Henei and several tens of others also came to the palace gates with axes and halberds seeking to appeal;", idiomatic: "his student Wang Diao of Bohai wore cangues and submitted a memorial proving Gu's innocence; Zhao Cheng of Henei and several dozen others also came to the palace gates bearing axes and halberds to appeal;" },
  { zh: "太后詔赦之。", literal: "The Empress Dowager issued an edict pardoning him.", idiomatic: "The Empress Dowager issued an edict pardoning him." },
  { zh: "及出獄，京師市裡皆稱萬歲。", literal: "When he came out of prison, throughout the capital markets and wards all cried \"Ten thousand years!\"", idiomatic: "When he left prison, people throughout the capital markets and wards cried \"Long live him!\"" },
  { zh: "冀聞之，大驚，畏固名德終為己害，乃更據奏前事。", literal: "Ji heard of it, was greatly alarmed, and feared Gu's fame and virtue would in the end harm him; he thereupon again memorialized on the earlier affair.", idiomatic: "Ji heard of it, was greatly alarmed, and feared Gu's fame and virtue would in the end harm him; he thereupon memorialized again on the earlier charges." },
  { zh: "大將軍長史吳祐傷固之枉，與冀爭之。", literal: "Grand General's Chief Clerk Wu You grieved Gu's injustice and disputed with Ji.", idiomatic: "The Grand General's chief clerk Wu You grieved Gu's injustice and argued with Ji." },
  { zh: "冀怒，不從。", literal: "Ji was angry and would not heed.", idiomatic: "Ji was angry and would not listen." },
  { zh: "從事中郎馬融主為冀作章表，融時在坐，祐謂融曰：「李公之罪，成於卿手。", literal: "Attendant Gentleman Ma Rong had the lead in drafting the memorial for Ji; Rong was then seated present. You said to Rong, \"Master Li's crime is completed by your hand.", idiomatic: "Attendant Gentleman Ma Rong took the lead in drafting the memorial for Ji; Rong was present at the time. You said to Rong, \"Master Li's crime is sealed by your hand.\"" },
  { zh: "李公若誅，卿何面目視天下人！", literal: "If Master Li is executed, with what face will you look upon the men of the realm!", idiomatic: "If Master Li is executed, with what face will you look upon the men of the realm!\"" },
  { zh: "」冀怒，起，入室；", literal: "\" Ji was angry, rose, and entered the inner room;", idiomatic: "\" Ji was angry, rose, and went into the inner room;" },
  { zh: "祐亦徑去。", literal: "You also departed directly.", idiomatic: "You also left at once." },
  { zh: "固遂死於獄中；", literal: "Gu thereupon died in prison;", idiomatic: "Gu thereupon died in prison;" },
  { zh: "臨命，與胡廣、趙戒書曰：「固受國厚恩，是以竭其股肱，不顧死亡，志欲扶持王室，比隆文、宣。", literal: "At the hour of death he wrote to Hu Guang and Zhao Jie, saying, \"Gu has received the state's thick favor; therefore I have exhausted my limbs, not caring for death, my will set on supporting the royal house and matching the grandeur of Wen and Xuan.", idiomatic: "At the hour of death he wrote to Hu Guang and Zhao Jie, saying, \"Gu has received the state's great favor; therefore I have exhausted myself, heedless of death, my will set on supporting the royal house and matching the glory of Emperors Wen and Xuan.\"" },
  { zh: "何圖一朝梁氏迷謬，公等曲從，以吉為凶，成事為敗乎！", literal: "Who could have foreseen that in a single morning the Liang clan would be deluded and err, and you gentlemen would bend and follow, making the auspicious into the inauspicious and success into failure!", idiomatic: "Who could have foreseen that in a single morning the Liang clan would go astray, and you gentlemen would bend and follow, turning the auspicious into the inauspicious and success into failure!\"" },
  { zh: "漢家衰微，從此始矣。", literal: "The Han house's decline begins from this.", idiomatic: "The Han house's decline begins from this." },
  { zh: "公等受主厚祿，顛而不扶，傾覆大事，後之良史豈有所私！", literal: "You gentlemen receive your lord's thick salary yet do not prop up what is toppling—overthrowing a great affair. Will later good historians show partiality!", idiomatic: "You gentlemen receive your lord's generous salary yet do not prop up what is toppling—you have overturned a great affair. Will later good historians show partiality!\"" },
  { zh: "固身已矣，於義得矣，夫復何言！", literal: "Gu's body is already done; in righteousness I have attained it—what more is there to say!", idiomatic: "My body is already done; in righteousness I have attained my end—what more is there to say!\"" },
  { zh: "」廣、戒得書悲慚，皆長歎流涕而已。", literal: "\" Guang and Jie received the letter, grieved and ashamed, and all could only sigh long and weep.", idiomatic: "\" Guang and Jie received the letter, grieved and ashamed, and could only sigh long and weep." },
  { zh: "冀使人脅杜喬曰：「早從宜，妻子可得全。", literal: "Ji sent someone to threaten Qiao, saying, \"Obey promptly and your wife and children may be kept whole.", idiomatic: "Ji sent someone to threaten Qiao, saying, \"Submit promptly and your wife and children may be spared.\"" },
  { zh: "」喬不肯。", literal: "\" Qiao would not consent.", idiomatic: "\" Qiao refused." },
  { zh: "明日，冀遣騎至其門，不聞哭者，遂白太后收系之；", literal: "The next day Ji sent horsemen to his gate; hearing no mourners, he thereupon reported to the Empress Dowager to seize and imprison him;", idiomatic: "The next day Ji sent horsemen to his gate; hearing no mourners, he reported to the Empress Dowager to seize and imprison him;" },
  { zh: "亦死獄中。", literal: "he too died in prison.", idiomatic: "He too died in prison." },
  { zh: "冀暴固、喬屍於城北四衢，令：「有敢臨者加其罪。", literal: "Ji exposed Gu's and Qiao's corpses at the four crossroads north of the city and ordered, \"Whoever dares to approach will have the crime added.", idiomatic: "Ji exposed Gu's and Qiao's corpses at the four crossroads north of the city and ordered, \"Whoever dares to approach will be punished further.\"" },
  { zh: "」固弟子汝南郭亮尚未冠，左提章、鉞，右秉鈇鍎，詣厥上書，乞收固屍，不報；", literal: "\" Gu's student Guo Liang of Runan had not yet attained the cap; in his left hand he carried seal and battle-axe, in his right he grasped axe and halberd, and went to the crossroads to submit a memorial begging to collect Gu's corpse—no reply;", idiomatic: "\" Gu's student Guo Liang of Runan had not yet come of age; in his left hand he carried a seal and battle-axe, in his right he held an axe and halberd, and went to the crossroads to submit a memorial begging to collect Gu's corpse—no reply;" },
  { zh: "與南陽董班俱往臨哭，守喪不去。", literal: "together with Dong Ban of Nanyang he went to mourn at the site and kept vigil without leaving.", idiomatic: "Together with Dong Ban of Nanyang he went to mourn at the site and kept vigil without leaving." },
  { zh: "夏門亭長呵之曰：「卿曹何等腐生！", literal: "The Xia Gate ward chief shouted at them, \"You lot—what sort of rotten scholars!", idiomatic: "The Xia Gate ward chief shouted at them, \"You lot—what sort of worthless scholars!\"" },
  { zh: "公犯詔書，欲干試有司乎！", literal: "The duke violated the edict—do you wish to provoke trial by the responsible offices!", idiomatic: "The duke violated the edict—do you wish to provoke the authorities!\"" },
  { zh: "」亮曰：「義之所動，豈知性命，何為以死相懼邪！", literal: "\" Liang said, \"What righteousness moves—how would I know life and death! Why use death to frighten us!", idiomatic: "\" Liang said, \"What righteousness moves me, I heed not life and death—why use death to frighten us!\"" },
  { zh: "」太后聞之，皆赦不誅。", literal: "\" The Empress Dowager heard of it and pardoned them both without execution.", idiomatic: "\" The Empress Dowager heard of it and pardoned them both." },
  { zh: "杜喬故掾陳留楊匡，號泣星行，到雒陽，著故赤幘，托為夏門亭吏，守護屍喪，積十二日；", literal: "Qiao's former clerk Yang Kuang of Chenliu wept and traveled by starlight to Luoyang, wore his old red headcloth, posed as a Xia Gate ward clerk, and guarded the corpse and mourning for twelve days in all;", idiomatic: "Qiao's former clerk Yang Kuang of Chenliu wept and traveled by night to Luoyang, wore his old red headcloth, posed as a Xia Gate ward clerk, and guarded the corpse and mourning for twelve days;" },
  { zh: "都官從事執之以聞，太后赦之。", literal: "An Attendant of the Capital Offices arrested him and reported; the Empress Dowager pardoned him.", idiomatic: "An attendant of the Capital Offices arrested him and reported; the Empress Dowager pardoned him." },
  { zh: "匡因詣厥上書，並乞李、杜二公骸骨，使得歸葬，太后許之。", literal: "Kuang thereupon went to the crossroads and submitted a memorial jointly begging the remains of the two masters Li and Du that they might be returned for burial; the Empress Dowager consented.", idiomatic: "Kuang thereupon went to the crossroads and submitted a memorial jointly begging the remains of Masters Li and Du for burial; the Empress Dowager consented." },
  { zh: "匡送喬喪還家，葬訖，行服，遂與郭亮、董班皆隱匿，終身不仕。", literal: "Kuang sent Qiao's funeral home; when burial was finished he observed mourning, and thereupon with Guo Liang and Dong Ban all went into hiding and to the end of their lives did not serve office.", idiomatic: "Kuang sent Qiao's funeral home; when burial was finished he observed mourning, and thereupon he, Guo Liang, and Dong Ban all went into hiding and never took office again." },
  { zh: "梁冀出吳祐為河間相，祐自免歸，卒於家。", literal: "Liang Ji sent Wu You out as Chancellor of Hejian; You resigned of himself and returned home, and died at home.", idiomatic: "Liang Ji sent Wu You out as chancellor of Hejian; You resigned and returned home, and died there." },
  { zh: "冀以劉鮪之亂，思朱穆之言，於是請種暠為從事中郎，薦欒巴為議郎，舉穆高第，為侍御史。", literal: "Because of Liu Yu's rebellion Ji reflected on Zhu Mu's words; he thereupon requested Zhong Gao as Attendant Gentleman, recommended Luan Ba as Protocol Gentleman, and nominated Mu with highest grade as Attendant Censor.", idiomatic: "Because of Liu Yu's rebellion Ji recalled Zhu Mu's words; he thereupon requested Zhong Gao as attendant gentleman, recommended Luan Ba as protocol gentleman, and nominated Mu with highest grade as attendant censor." },
  { zh: "是歲，南單于兜樓儲死，伊陵屍逐就單于車兒立。", literal: "This year the Southern Chanyu Doulowu Chu died; Yiling Shizhu Jiu made Chanyu Cher stand.", idiomatic: "This year the Southern Chanyu Doulowu Chu died; Yiling Shizhu Jiu installed Cher as chanyu." },
  { zh: "春，正月，甲子，帝加元服。", literal: "In spring, the first month, on the day jiazi, the emperor added the full cap and robes.", idiomatic: "In spring, in the first month, on jiazi day the emperor assumed the full cap and robes of adulthood." },
  { zh: "庚午，赦天下。", literal: "On the day gengwu he pardoned the realm.", idiomatic: "On gengwu day he pardoned the realm." },
  { zh: "三月，戊辰，帝從皇太后幸大將軍冀府。", literal: "In the third month, on the day wuchen, the emperor followed the Empress Dowager on a visit to the Grand General Ji's residence.", idiomatic: "In the third month, on wuchen day, the emperor accompanied the Empress Dowager on a visit to Grand General Ji's residence." },
  { zh: "白馬羌寇廣漢屬國，殺長吏。", literal: "The White Horse Qiang raided the Dependent State of Guanghan and killed the chief official.", idiomatic: "The White Horse Qiang raided the Dependent State of Guanghan and killed the chief official." },
  { zh: "益州刺史率板楯蠻討破之。", literal: "The Inspector of Yizhou led the Banshipi barbarians in a campaign and defeated them.", idiomatic: "The inspector of Yizhou led the Banshipi in a campaign and defeated them." },
  { zh: "夏，四月，丙子，封帝弟顧為平原王，奉孝崇皇祀；", literal: "In summer, the fourth month, on the day bingzi, the emperor's younger brother Gu was enfeoffed as King of Pingyuan, to maintain the sacrifices to Xiao Chong Huang;", idiomatic: "In summer, in the fourth month, on bingzi day, the emperor's younger brother Gu was enfeoffed as King of Pingyuan to maintain the sacrifices to Xiao Chong Huang;" },
  { zh: "尊孝崇皇夫人馬氏為孝崇園貴人。", literal: "the lady Ma, consort of Xiao Chong Huang, was honored as Noble Lady of the Garden of Xiao Chong.", idiomatic: "the lady Ma, consort of Xiao Chong Huang, was honored as noble lady of the garden of Xiao Chong." },
  { zh: "五月，癸丑，北宮掖廷中德陽殿及左掖門火，車駕移幸南宮。", literal: "In the fifth month, on the day guichou, Deyang Hall in the Northern Palace palace women's quarters and the Left Women's Gate caught fire; the imperial carriage moved to favor the Southern Palace.", idiomatic: "In the fifth month, on guichou day, Deyang Hall in the Northern Palace women's quarters and the Left Women's Gate caught fire; the imperial carriage moved to the Southern Palace." },
  { zh: "六月，改清河為甘陵。", literal: "In the sixth month Qinghe was changed to Ganling.", idiomatic: "In the sixth month Qinghe was renamed Ganling." },
  { zh: "立安平孝王得子經侯理為甘陵王。", literal: "Anping Xiao Wang De's son, Marquis Jing Li, was installed as King of Ganling.", idiomatic: "Anping Xiao Wang De's son, Marquis Jing Li, was installed as King of Ganling." },
  { zh: "奉孝德皇祀。", literal: "To maintain the sacrifices to Xiao De Huang.", idiomatic: "to maintain the sacrifices to Xiao De Huang." },
  { zh: "秋，七月，京師大水。", literal: "In autumn, the seventh month, the capital suffered great flood.", idiomatic: "In autumn, in the seventh month, the capital suffered a great flood." },
  { zh: "夏，四月，丁卯晦，日有食之。", literal: "In summer, the fourth month, on the last day dingmao, the sun was eclipsed.", idiomatic: "In summer, in the fourth month, on the last day of the cycle, dingmao, there was a solar eclipse." },
  { zh: "秋，八月，乙丑，有星孛於天市。", literal: "In autumn, the eighth month, on the day yichou, a comet appeared in the Market constellation.", idiomatic: "In autumn, in the eighth month, on yichou day a comet appeared in the Market constellation." },
  { zh: "京師大水。", literal: "The capital suffered great flood.", idiomatic: "The capital suffered a great flood." },
  { zh: "九月，己卯，地震。", literal: "In the ninth month, on the day jimao, earthquake.", idiomatic: "In the ninth month, on jimao day, there was an earthquake." },
  { zh: "庚寅，地又震。", literal: "On the day gengyin the ground shook again.", idiomatic: "On gengyin day the ground shook again." },
  { zh: "郡、國五山崩。", literal: "In five commanderies and states mountains collapsed.", idiomatic: "In five commanderies and kingdoms mountains collapsed." },
  { zh: "冬，十月，太尉趙戒免；", literal: "In winter, the tenth month, Grand Commandant Zhao Jie was dismissed;", idiomatic: "In winter, in the tenth month, Grand Commandant Zhao Jie was dismissed;" },
  { zh: "以司徒袁湯為太尉，大司農河內張歆為司徒。", literal: "Minister over the Masses Yuan Tang was made Grand Commandant, and Grand Minister of Agriculture Zhang Xin of Henei was made Minister over the Masses.", idiomatic: "Minister over the Masses Yuan Tang was made grand commandant, and Grand Minister of Agriculture Zhang Xin of Henei was made minister over the masses." },
  { zh: "是歲，前朗陵侯相荀淑卒。", literal: "This year the former Chancellor of Langling Marquisate Xun Shu died.", idiomatic: "This year the former chancellor of the Langling marquisate, Xun Shu, died." },
  { zh: "淑少博學有高行，當世名賢李固、李膺皆師宗之。", literal: "Shu in youth was broadly learned and had lofty conduct; the age's famous worthies Li Gu and Li Ying all took him as master and model.", idiomatic: "Shu in youth was broadly learned and of lofty conduct; the age's famous worthies Li Gu and Li Ying all took him as master and model." },
  { zh: "在朗陵、蒞事明治，稱為神君。", literal: "In Langling, in handling affairs he was enlightened in governance, and was called the Divine Lord.", idiomatic: "In Langling, in handling affairs he governed with clarity, and was called the Divine Lord." },
  { zh: "有子八人：儉、緄、靖、燾、汪、爽、肅、專，並有名稱，時人謂之八龍。", literal: "He had eight sons: Jian, Gun, Jing, Tao, Wang, Shuang, Su, and Zhuan—all had famous reputations; men of the time called them the Eight Dragons.", idiomatic: "He had eight sons: Jian, Gun, Jing, Tao, Wang, Shuang, Su, and Zhuan—all had famous reputations; men of the time called them the Eight Dragons." },
  { zh: "所居裡舊名西豪，穎陰令渤海苑康以為昔高陽氏有才子八人，更命其裡曰高陽裡。", literal: "The lane where they dwelt was formerly named West Splendor; the magistrate of Yingyin, Fan Kang of Bohai, considering that of old Gaoyang Shi had eight talented sons, renamed their lane Gaoyang Lane.", idiomatic: "The lane where they lived was formerly named West Splendor; the magistrate of Yingyin, Fan Kang of Bohai, reflecting that of old Gaoyang Shi had eight talented sons, renamed their lane Gaoyang Lane." },
  { zh: "膺性簡亢，無所交接，唯以淑為師，以同郡陳寔為友。", literal: "Ying's nature was simple and lofty; he had no associations—only with Shu as master and with Chen Shi of the same commandery as friend.", idiomatic: "Ying's nature was simple and lofty; he associated with almost no one—only with Shu as master and with Chen Shi of the same commandery as friend." },
  { zh: "荀爽嘗就謁膺，因為其御；", literal: "Xun Shuang once went to visit Ying and for that reason drove his carriage;", idiomatic: "Xun Shuang once went to visit Ying and for that reason drove his carriage;" },
  { zh: "既還，喜曰：「今日乃得御李君矣！", literal: "When he returned he rejoiced, saying, \"Today I have finally gotten to drive for Master Li!", idiomatic: "When he returned he rejoiced, saying, \"Today I have finally gotten to drive for Master Li!\"" },
  { zh: "」其見慕如此。", literal: "\" He was admired to this degree.", idiomatic: "\" He was admired to this degree." },
  { zh: "陳寔出於單微，為郡西門亭長。", literal: "Chen Shi came from humble origins and was the West Gate pavilion chief of the commandery.", idiomatic: "Chen Shi came from humble origins and was the West Gate pavilion chief of the commandery." },
  { zh: "同郡錘皓以篤行稱，前後九辟公府，年輩遠在寔前，引與為友。", literal: "Zhong Hao of the same commandery was famed for earnest conduct; nine times before and after he was summoned to the ducal offices; his years ranked far before Shi—yet he drew him in as friend.", idiomatic: "Zhong Hao of the same commandery was famed for earnest conduct and was nine times summoned to the ducal offices; though far his senior in years, he drew Shi in as a friend." },
  { zh: "皓為郡功曹，辟司徒府；", literal: "Hao was the commandery's Merit Officer and was summoned to the Steward's office;", idiomatic: "Hao was the commandery merit officer and was summoned to the Steward's office;" },
  { zh: "臨辭，太守問：「誰可代卿者？", literal: "On taking leave the Administrator asked, \"Who can replace you?", idiomatic: "On taking leave the administrator asked, \"Who can replace you?\"" },
  { zh: "」皓曰：「明府欲必得其人，西門亭長陳寔可。", literal: "\" Hao said, \"If the Excellency wishes surely to obtain the right man, the West Gate pavilion chief Chen Shi will do.", idiomatic: "\" Hao said, \"If Your Excellency wishes surely to obtain the right man, the West Gate pavilion chief Chen Shi will do.\"" },
  { zh: "」寔聞之曰：「鐘君似不察人，不知何獨識我！", literal: "\" When Shi heard it he said, \"Master Zhong seems not to discern men—why does he alone know me!", idiomatic: "\" When Shi heard it he said, \"Master Zhong seems not to discern men—why does he alone recognize me!\"" },
  { zh: "」太守遂以寔為功曹。", literal: "\" The Administrator thereupon made Shi Merit Officer.", idiomatic: "\" The administrator thereupon made Shi merit officer." },
  { zh: "時中常侍山陽侯覽托太守高倫用吏，倫教署為文學掾，寔知非其人，懷檄請見，言曰：「此人不宜用，而侯常侍不可違，寔乞從外署，不足以塵明德。", literal: "At that time the Palace Attendant Marquis of Shanyang Hou Lan had asked the Administrator Gao Lun to employ an official; Lun had him appointed as Literary Adjunct. Shi knew he was not the right man, carried the appointment slip and requested audience, saying, \"This man should not be employed, yet the Marquis Regular Attendant cannot be disobeyed—Shi begs to have him assigned from an outside posting, not enough to soil the Excellency's bright virtue.", idiomatic: "At that time Palace Attendant Marquis of Shanyang Hou Lan had asked Administrator Gao Lun to employ an official; Lun had him appointed literary adjutant. Shi knew he was unfit, carried the appointment slip and requested audience, saying, \"This man should not be employed, yet the marquis regular attendant cannot be disobeyed—Shi begs to have him assigned from an outside posting, lest he soil Your Excellency's bright virtue.\"" },
  { zh: "」倫從之。", literal: "\" Lun complied.", idiomatic: "\" Lun complied." },
  { zh: "於是鄉論怪其非舉，寔終無所言。", literal: "Thereupon county opinion wondered at his failure to recommend; Shi to the end said nothing.", idiomatic: "Thereupon local opinion wondered at his failure to recommend the man; Shi to the end said nothing." },
  { zh: "倫後被征為尚書，郡中士大夫送至綸氏，倫謂眾人曰：「吾前為侯常侍用吏，陳君密持教還而於外白署，比聞議者以此少之，此咎由故人畏憚強禦，陳君可謂『善則稱君，過則稱己』者也。", literal: "Later Lun was summoned as Master of Writing; the commandery's scholar-officials saw him off to Lunshi. Lun told the crowd, \"Earlier when I employed an official for the Marquis Regular Attendant, Master Chen secretly held back the instruction and returned it, then openly posted him from outside. Recently I hear critics have on this account slighted him. This fault was mine—fearing the strong and overbearing of old. Master Chen may be called one who 'in good calls it the lord's, in fault calls it his own.'", idiomatic: "Later Lun was summoned as master of writing; the commandery's scholar-officials saw him off to Lunshi. Lun told the crowd, \"Earlier when I employed an official for the marquis regular attendant, Master Chen secretly held back the instruction and returned it, then openly posted him from outside. Recently I hear critics have on this account slighted him. This fault was mine—fearing the strong and overbearing. Master Chen may be called one who 'in good calls it the lord's, in fault calls it his own.'\"" },
  { zh: "」寔固自引愆，聞者方歎息，由是天下服其德。", literal: "\" Shi firmly took the blame on himself; hearers then sighed with admiration, and from this all under Heaven submitted to his virtue.", idiomatic: "\" Shi firmly took the blame on himself; hearers then sighed with admiration, and from this all under Heaven submitted to his virtue." },
  { zh: "後為太丘長，修德清靜，百姓以安。", literal: "Later he was magistrate of Taqiu; he cultivated virtue in purity and quiet, and the hundred households were at peace.", idiomatic: "Later he was magistrate of Taqiu; he cultivated virtue in purity and quiet, and the people were at peace." },
  { zh: "鄰縣民歸附者，寔輒訓導譬解發遣，各令還本。", literal: "When people of neighboring counties came to attach themselves, Shi would instruct, guide, and explain, then send them off, each ordered to return to his native place.", idiomatic: "When people of neighboring counties came to attach themselves, Shi would instruct and explain, then send them off, each ordered to return home." },
  { zh: "司官行部，吏慮民有訟者，白欲禁之。", literal: "When the supervising official made his circuit of the department, clerks feared there would be litigants among the people and reported wishing to forbid it.", idiomatic: "When the supervising official made his circuit, clerks feared the people would litigate and reported wishing to forbid it." },
  { zh: "寔曰：「訟以求直，禁之，理將何申！", literal: "Shi said, \"Litigation seeks straightness—if forbidden, how will principle be expressed!", idiomatic: "Shi said, \"Litigation seeks justice—if forbidden, how will right be upheld!\"" },
  { zh: "其勿有所拘。", literal: "Do not restrict them.", idiomatic: "Do not restrict them.\"" },
  { zh: "」司官聞而歎息曰：「陳君所言若是，豈有冤於人乎！", literal: "\" The supervising official heard and sighed, \"If Master Chen speaks thus, how could anyone be wronged!", idiomatic: "\" The supervising official heard and sighed, \"If Master Chen speaks thus, how could anyone be wronged!\"" },
  { zh: "」亦竟無訟者。", literal: "\" And to the end there were no litigants.", idiomatic: "\" And in the end there were no litigants." },
  { zh: "以沛相賦斂違法，解印綬去；", literal: "Because as Chancellor of Pei his levies violated the law, he surrendered seal and cord and left;", idiomatic: "Because as chancellor of Pei his levies violated the law, he surrendered his seal and cord and left;" },
  { zh: "吏民追思之。", literal: "officials and people long remembered him.", idiomatic: "officials and people long remembered him." },
  { zh: "鐘皓素與荀淑齊名，李膺常歎曰：「荀君清識難尚，鐘君至德可師。", literal: "Zhong Hao had always been equal in fame with Xun Shu; Li Ying often sighed, \"Master Xun's pure discernment is hard to match; Master Zhong's utmost virtue may be taken as teacher.", idiomatic: "Zhong Hao had always been equal in fame with Xun Shu; Li Ying often sighed, \"Master Xun's pure discernment is hard to match; Master Zhong's utmost virtue may be taken as teacher.\"" },
  { zh: "」皓兄子瑾母，膺之姑也。", literal: "\" Hao's elder brother's son Jin—his mother was Ying's paternal aunt.", idiomatic: "\" Hao's elder brother's son Jin—his mother was Ying's paternal aunt." },
  { zh: "瑾好學慕古，有退讓風，與膺同年，俱有聲名。", literal: "Jin loved learning and admired antiquity, had a manner of yielding; with Ying he was the same age and both had reputation.", idiomatic: "Jin loved learning and admired antiquity, had a manner of yielding; he was Ying's age and both had reputation." },
  { zh: "膺祖太尉修常言：「瑾似我家性，『邦有道，不廢；", literal: "Ying's grandfather the Grand Commandant Xiu often said, \"Jin resembles our family's nature: 'When the state has the Way, he is not set aside;", idiomatic: "Ying's grandfather Grand Commandant Xiu often said, \"Jin resembles our family's nature: 'When the state has the Way, he is not set aside;\"" },
  { zh: "邦無道，免於刑戮。", literal: "when the state lacks the Way, he escapes punishment and execution.'", idiomatic: "when the state lacks the Way, he escapes punishment and execution.'\"" },
  { zh: "』」復以膺妹妻之。", literal: "\" Again he gave Ying's younger sister in marriage to him.", idiomatic: "\" Again he gave Ying's younger sister in marriage to him." },
  { zh: "膺謂瑾曰：「孟子以為『人無是非之心，非人也』，弟於是何太無皁白邪！", literal: "Ying said to Jin, \"Mencius held that 'a man without a heart of right and wrong is not human'—younger brother, why are you so utterly without black and white!", idiomatic: "Ying said to Jin, \"Mencius held that 'a man without a heart of right and wrong is not human'—younger brother, why are you so utterly without black and white!\"" },
  { zh: "」瑾嘗以膺言白皓。", literal: "\" Jin once reported Ying's words to Hao.", idiomatic: "\" Zhong Jin once reported Li Ying's words to Zhong Hao." },
  { zh: "皓曰：「元禮祖、父在位，諸宗並盛，故得然乎！", literal: "Hao said: \"Yuanli's grandfather and father held office, all the clansmen flourished together—so he could be like this!", idiomatic: "Hao said, \"Yuanli's grandfather and father held office, all the clansmen flourished together—so he could be like this!" },
  { zh: "昔國武子好招人過，以致怨惡，今豈其時邪！", literal: "In old times Guo Wuzi liked to summon others' faults, bringing hatred and ill will—is today such a time?", idiomatic: "In old times Guo Wuzi liked to call out others' faults and brought hatred and ill will upon himself—is today such a time?" },
  { zh: "必欲保身全家，爾道為貴。", literal: "If you must preserve body and whole family, your way is precious.\"", idiomatic: "If you must preserve your body and your whole family, your way is the noble one.\"" },
  { zh: "春，正月，甲子，赦天下。", literal: "In spring, the first month, on jiazi, amnesty was granted to all under Heaven.", idiomatic: "In spring, in the first month, on jiazi day, amnesty was granted to all under Heaven." },
  { zh: "改元。", literal: "The reign era was changed.", idiomatic: "The reign era was changed." },
  { zh: "乙丑，太后詔歸政於帝，始罷稱制。", literal: "On yichou, the empress dowager issued an edict returning government to the emperor and ceased ruling in her own name.", idiomatic: "On yichou day, the empress dowager issued an edict returning government to the emperor and ceased ruling in her own name." },
  { zh: "二月，甲寅，太后梁氏崩。", literal: "In the second month, on jiayin, Empress Dowager Liang died.", idiomatic: "In the second month, on jiayin day, Empress Dowager Liang died." },
  { zh: "三月，車駕徙幸北宮。", literal: "In the third month, the imperial carriage moved to reside at the Northern Palace.", idiomatic: "In the third month, the imperial carriage moved to reside at the Northern Palace." },
  { zh: "甲午，葬順烈皇后。", literal: "On jiawu, Empress Shunlie was buried.", idiomatic: "On jiawu day, Empress Shunlie was buried." },
  { zh: "增封大將軍冀萬戶，並前合三萬戶；", literal: "Grand General-in-Chief Ji was granted an additional ten thousand households, totaling thirty thousand with previous grants;", idiomatic: "Grand General-in-Chief Liang Ji was granted an additional ten thousand households, totaling thirty thousand with previous grants;" },
  { zh: "封冀妻孫壽為襄城君，兼食陽翟租，歲入五千萬，加賜赤紱，比長公主。", literal: "Ji's wife Sun Shou was enfeoffed as Lady of Xiangcheng, also receiving Yangdi rents with annual income of fifty million, and was given a crimson sash like an emperor's sister.", idiomatic: "Liang Ji's wife Sun Shou was enfeoffed as Lady of Xiangcheng, also receiving Yangdi rents with annual income of fifty million, and was given a crimson sash like an emperor's sister." },
  { zh: "壽善為妖態以蠱惑冀，冀甚寵憚之。", literal: "Shou was skilled at seductive postures to bewitch Ji; Ji greatly favored and feared her.", idiomatic: "Sun Shou was skilled at seductive postures to bewitch Liang Ji; Ji greatly favored and feared her." },
  { zh: "冀愛監奴秦宮，官至太倉令，得出入壽所，威權大震，刺史、二千石皆謁辭之。", literal: "Ji favored his steward-slave Qin Gong, who rose to Grand Granary Intendant, could enter Shou's quarters, and his authority greatly shook—inspectors and 2000-dan officials all called and bowed to him.", idiomatic: "Liang Ji favored his steward-slave Qin Gong, who rose to Grand Granary Intendant, could enter Sun Shou's quarters, and whose authority greatly shook the realm—inspectors and 2000-dan officials all called on him and bowed." },
  { zh: "冀與壽對街為宅，殫極土木，互相誇競，金玉珍怪，充積藏室；", literal: "Ji and Shou built mansions facing each other across the street, exhausting themselves in construction and vying in display—gold, jade, and rare treasures filled their storehouses;", idiomatic: "Liang Ji and Sun Shou built mansions facing each other across the street, exhausting themselves in construction and vying in display—gold, jade, and rare treasures filled their storehouses;" },
  { zh: "又廣開園圃，采土築山，十里九阪，深林絕澗，有若自然，奇禽馴獸飛走其間。", literal: "They also vastly opened gardens, heaped earth to build hills—nine slopes in ten li, deep forests and sheer ravines as if natural, with strange birds and tame beasts flying and running among them.", idiomatic: "They also vastly opened gardens and heaped earth to build hills—nine slopes in ten li, deep forests and sheer ravines as if natural, with strange birds and tame beasts flying and running among them." },
  { zh: "冀、壽共乘輦車，遊觀第內，多從倡伎，酣謳竟路。", literal: "Ji and Shou rode the imperial carriage together touring within their mansions, with many singing girls, drunken song filling the roads.", idiomatic: "Liang Ji and Sun Shou rode the imperial carriage together touring within their mansions, with many singing girls, drunken song filling the roads." },
  { zh: "或連日繼夜以聘娛恣。", literal: "Sometimes for days and nights without stop they indulged in entertainment.", idiomatic: "Sometimes for days and nights without stop they indulged in entertainment." },
  { zh: "客到門不得通，皆請謝門者，門者累千金。", literal: "Guests reaching the gate could not pass—all had to plead with the gatekeepers, and gatekeepers amassed thousands in gold.", idiomatic: "Guests reaching the gate could not pass—all had to plead with the gatekeepers, and gatekeepers amassed thousands in gold." },
  { zh: "又多拓林苑，周遍近縣，起兔苑於河南城西，經亙數十里，移檄所在調發生兔，刻其毛以為識，人有犯者，罪至死刑。", literal: "They again greatly expanded forest parks encircling nearby counties, raised a Rabbit Park west of Henan city stretching tens of li, sent orders everywhere to levy live rabbits and brand their fur for identification—violators were punished up to death.", idiomatic: "They again greatly expanded forest parks encircling nearby counties, raised a Rabbit Park west of Henan city stretching tens of li, sent orders everywhere to levy live rabbits and brand their fur for identification—violators were punished up to death." },
  { zh: "嘗有西域賈胡不知禁忌，誤殺一兔，轉相告言，坐死者十餘人。", literal: "Once a Western Regions merchant did not know the taboo and mistakenly killed a rabbit; the story spread and more than ten were executed.", idiomatic: "Once a Western Regions merchant did not know the taboo and mistakenly killed a rabbit; the story spread and more than ten were executed." },
  { zh: "又起別第於城西，以納奸亡；", literal: "They also built separate mansions west of the city to harbor criminals and fugitives;", idiomatic: "They also built separate mansions west of the city to harbor criminals and fugitives;" },
  { zh: "或取良人悉為奴婢，至數千口，名曰自賣人。", literal: "sometimes taking respectable people entirely as slaves, to several thousand persons called \"self-sellers.\"", idiomatic: "sometimes taking respectable people entirely as slaves, to several thousand persons called \"self-sellers.\"" },
  { zh: "冀用壽言，多斥奪諸梁在位者，外以示謙讓，而實崇孫氏。", literal: "Ji followed Shou's advice, repeatedly ousting Liangs in office, outwardly showing humility while actually elevating the Sun clan.", idiomatic: "Liang Ji followed Sun Shou's advice, repeatedly ousting Liangs in office, outwardly showing humility while actually elevating the Sun clan." },
  { zh: "孫氏宗親冒名為侍中、卿、校、郡守、長吏者十餘人，皆貪饕凶淫，各遣私客籍屬縣富人，被以它罪，閉獄掠拷，使出錢自贖，貲物少者至於死、徙。", literal: "More than ten Sun kinsmen falsely held titles as Palace Attendant, minister, colonel, or commandery administrator—all greedy, fierce, and lewd; each sent private agents to register wealthy men in affiliated counties, charged other crimes, imprisoned and tortured them to pay ransom, and those with little goods died or were banished.", idiomatic: "More than ten Sun kinsmen falsely held titles as Palace Attendant, minister, colonel, or commandery administrator—all greedy, fierce, and lewd. Each sent private agents to register wealthy men in affiliated counties, charged other crimes, imprisoned and tortured them to pay ransom, and those with little goods died or were banished." },
  { zh: "扶風人士孫奮，居富而性吝，冀以馬乘遺之，從貸錢五千萬，奮以三千萬與之。", literal: "Shisun Fen of Fufeng was rich but stingy; Ji sent him horses and carriages as gifts and lent fifty million—Fen gave only thirty million.", idiomatic: "Shisun Fen of Fufeng was rich but stingy. Liang Ji sent him horses and carriages as gifts and lent fifty million—Fen gave only thirty million." },
  { zh: "冀大怒，乃告郡縣，認奮母為其守藏婢，雲盜白珠十斛、紫金千斤以叛，遂收考奮兄弟死於獄中，悉沒貲財億七千餘萬。", literal: "Ji in great rage reported to commanderies and counties that Fen's mother was his treasure-keeping maid who stole ten hu of white pearls and a thousand jin of purple gold to rebel; Fen and his brothers died in prison, and more than 170 million in goods were confiscated.", idiomatic: "Liang Ji in great rage reported to commanderies and counties that Fen's mother was his treasure-keeping maid who stole ten hu of white pearls and a thousand jin of purple gold to rebel. Fen and his brothers died in prison, and more than 170 million in goods were confiscated." },
  { zh: "冀又遣客周流四方，遠至塞外，廣求異物，而使人復乘勢橫暴，妻略婦女，驅擊吏卒，所在怨毒。", literal: "Ji also sent agents circulating everywhere, even to the frontier, widely seeking rare goods; his men again used their power to rampage, seize women, drive and strike officials and soldiers—resentment everywhere.", idiomatic: "Liang Ji also sent agents circulating everywhere, even to the frontier, widely seeking rare goods. His men again used their power to rampage, seize women, drive and strike officials and soldiers—resentment everywhere." },
  { zh: "侍御史朱穆自以冀故吏，奏記諫曰：「明將軍地有申伯之尊，位為群公之首，一日行善，天下歸仁；", literal: "Attendant Censor Zhu Mu, considering himself a former subordinate of Ji, submitted a private memorial of remonstrance, saying: \"Illustrious General, your position has the dignity of the Earl of Shen and you stand first among the nobles—one day of doing good and the realm turns to benevolence;", idiomatic: "Attendant Censor Zhu Mu, considering himself a former subordinate of Liang Ji, submitted a private memorial of remonstrance, saying, \"Illustrious General, your position has the dignity of the Earl of Shen and you stand first among the nobles—one day of doing good and the realm turns to benevolence;" },
  { zh: "終朝為惡，四海傾覆。", literal: "a whole morning of doing evil and the four seas overturn.", idiomatic: "a whole morning of doing evil and the four seas overturn." },
  { zh: "頃者官民俱匱，加以水蟲為害，京師諸官費用增多，詔書發調，或至十倍，各言官無見財，皆當出民，手旁掠割剝，強令充足。", literal: "Recently officials and people alike are impoverished, and locusts and insects add harm; capital offices' expenses have increased, and edicts for levies sometimes reach tenfold—each saying the office has no ready funds and all must come from the people, with hands at their sides plundering and stripping, forcibly making quotas full.", idiomatic: "Recently officials and people alike are impoverished, and locusts and insects add harm. Capital offices' expenses have increased, and edicts for levies sometimes reach tenfold—each saying the office has no ready funds and all must come from the people, with hands at their sides plundering and stripping, forcibly making quotas full." },
  { zh: "公賦既重，私斂又深，牧守長吏多非德選，貪聚無厭，遇民如虜，或絕命於棰楚之下，或自賊於迫切之求。", literal: "Public levies are already heavy and private exactions still deeper; many prefects and administrators were not chosen for virtue—greedy accumulation without end, treating the people like captives, some dying under the rod, others destroying themselves under urgent demands.", idiomatic: "Public levies are already heavy and private exactions still deeper. Many prefects and administrators were not chosen for virtue—greedy accumulation without end, treating the people like captives, some dying under the rod, others destroying themselves under urgent demands." },
  { zh: "又掠奪百姓，皆托之尊府，遂令將軍結怨天下，吏民酸毒，道路歎嗟。", literal: "Again plundering the people, all attributing it to your exalted mansion—thus the General has incurred the realm's resentment, officials and people are bitter and poisoned, and the roads are filled with sighs.", idiomatic: "Again plundering the people, all attributing it to your exalted mansion—thus the General has incurred the realm's resentment, officials and people are bitter and poisoned, and the roads are filled with sighs." },
  { zh: "昔永和之末，綱紀少弛，頗失人望，四五歲耳，而財空戶散，下有離心，馬勉之徒乘敝而起，荊、揚之間幾成大患；", literal: "At the end of Yonghe, discipline slackened somewhat and popular regard was lost—only four or five years, yet treasuries emptied and households scattered, subordinates had a mind to leave, and men like Ma Mian seized weakness to rise; between Jing and Yang it nearly became a great calamity;", idiomatic: "At the end of Yonghe, discipline slackened somewhat and popular regard was lost—only four or five years, yet treasuries emptied and households scattered, subordinates had a mind to leave, and men like Ma Mian seized weakness to rise. Between Jing and Yang it nearly became a great calamity;" },
  { zh: "幸賴順烈皇后初政清靜，內外同力，僅乃討定。", literal: "fortunately relying on Empress Shunlie's early rule of quiet purity and united effort within and without, it was barely pacified.", idiomatic: "fortunately relying on Empress Shunlie's early rule of quiet purity and united effort within and without, it was barely pacified." },
  { zh: "今百姓戚戚，困於永和，內非仁愛之心可得容忍，外非守國之計所宜久安也。", literal: "Now the people are anxious and distressed, trapped as in Yonghe—inwardly this is not what a benevolent heart can tolerate, outwardly this is not what a plan to guard the state can long endure.", idiomatic: "Now the people are anxious and distressed, trapped as in Yonghe—inwardly this is not what a benevolent heart can tolerate, outwardly this is not what a plan to guard the state can long endure." },
  { zh: "夫將相大臣，均體元首，共輿而馳，同舟而濟，輿傾舟覆，患實共之。", literal: "Generals, ministers, and great officials share the ruler's body, ride the same carriage and row the same boat—if carriage tips or boat capsizes, the harm is truly shared.", idiomatic: "Generals, ministers, and great officials share the ruler's body, ride the same carriage and row the same boat—if the carriage tips or the boat capsizes, the harm is truly shared." },
  { zh: "豈可以去明即昧，履危自安，主孤時困而莫之恤乎！", literal: "How can one leave clarity for darkness, tread danger for personal safety, while the ruler is isolated, the times distressed, and no one pities him!", idiomatic: "How can one leave clarity for darkness, tread danger for personal safety, while the ruler is isolated, the times distressed, and no one pities him!" },
  { zh: "宜時易宰守非其人者，減省第宅園池之費，拒絕郡國諸所奉送，內以自明，外解人惑；", literal: "You should promptly replace unfit prefects and administrators, reduce expenses on mansions, gardens, and pools, refuse all gifts sent from commanderies and kingdoms—inwardly to clarify yourself, outwardly to dissolve people's confusion;", idiomatic: "You should promptly replace unfit prefects and administrators, reduce expenses on mansions, gardens, and pools, refuse all gifts sent from commanderies and kingdoms—inwardly to clarify yourself, outwardly to dissolve people's confusion;" },
  { zh: "使挾奸之吏無所依托，司察之臣得盡耳目。", literal: "let corrupt officials have nowhere to lean, and inspecting ministers use their eyes and ears fully.", idiomatic: "let corrupt officials have nowhere to lean, and inspecting ministers use their eyes and ears fully." },
  { zh: "憲度既張，遠邇清壹，則將軍身尊事顯，德燿無窮矣！", literal: "Once law and measure are displayed, far and near are pure and unified—then the General's person will be honored, affairs manifest, and virtue shine without end!\"", idiomatic: "Once law and measure are displayed, far and near are pure and unified—then the General's person will be honored, affairs manifest, and virtue shine without end!\"" },
  { zh: "」冀不納。", literal: "\" Ji did not accept this.", idiomatic: "\" Liang Ji did not accept this." },
  { zh: "冀雖專朝縱橫，而猶交結左右宦官，任其子弟、賓客以為州郡要職，欲以自固恩寵。", literal: "Though Ji monopolized the court and ranged freely, he still cultivated eunuchs at the ruler's side, placing his sons, younger relatives, and clients in key provincial posts to secure favor and power.", idiomatic: "Though Liang Ji monopolized the court and ranged freely, he still cultivated eunuchs at the ruler's side, placing his sons, younger relatives, and clients in key provincial posts to secure favor and power." },
  { zh: "穆又奏記極諫，冀終不悟，報書云：「如此，僕亦無一可邪！", literal: "Mu again submitted a memorial of utmost remonstrance; Ji still did not awaken and replied: \"If so, then your servant has not one merit!", idiomatic: "Zhu Mu again submitted a memorial of utmost remonstrance. Liang Ji still did not awaken and replied, \"If so, then your servant has not one merit!" },
  { zh: "」然素重穆，亦不甚罪也。", literal: "\" Yet he had always valued Mu and did not greatly punish him.", idiomatic: "\" Yet he had always valued Zhu Mu and did not greatly punish him." },
  { zh: "冀遣書詣樂安太守陳蕃，有所請托，不得通。", literal: "Ji sent a letter to Administrator of Lean Chen Fan with a request, but it was not delivered.", idiomatic: "Liang Ji sent a letter to Administrator of Lean Chen Fan with a request, but it was not delivered." },
  { zh: "使者詐稱它客求謁蕃；", literal: "The envoy falsely claimed to be another guest seeking an audience with Fan;", idiomatic: "The envoy falsely claimed to be another guest seeking an audience with Fan;" },
  { zh: "蕃怒，笞殺之。", literal: "Fan in anger had him flogged to death.", idiomatic: "Chen Fan in anger had him flogged to death." },
  { zh: "坐左轉修武令。", literal: "For this he was demoted to Magistrate of Xiuwu.", idiomatic: "For this he was demoted to Magistrate of Xiuwu." },
  { zh: "時皇子有疾，下郡縣市珍藥，而冀遣客繼書詣京兆，並貨牛黃。", literal: "When a prince was ill, commanderies and counties were ordered to buy rare medicines; Ji sent agents with successive letters to the capital region to hoard bezoar as well.", idiomatic: "When a prince was ill, commanderies and counties were ordered to buy rare medicines. Liang Ji sent agents with successive letters to the capital region to hoard bezoar as well." },
  { zh: "京兆尹南陽延篤發書收客，曰：「大將軍椒房外家，而皇子有疾，必應陳進醫方，豈當使客千里求利乎！", literal: "Intendant of the capital region Yan Du of Nanyang opened the letter and arrested the agent, saying: \"The Grand General is the empress's kin by marriage—when a prince is ill he should surely present medical prescriptions; how can he send agents a thousand li to seek profit!", idiomatic: "Intendant of the capital region Yan Du of Nanyang opened the letter and arrested the agent, saying, \"The Grand General is the empress's kin by marriage—when a prince is ill he should surely present medical prescriptions. How can he send agents a thousand li to seek profit!" },
  { zh: "」遂殺之。", literal: "\" He then killed him.", idiomatic: "\" He then killed him." },
  { zh: "冀慚而不得言。", literal: "Ji was ashamed but could say nothing.", idiomatic: "Liang Ji was ashamed but could say nothing." },
  { zh: "有司承旨求其事，篤以病免。", literal: "The responsible offices, following the intent, investigated the matter; Du was dismissed on grounds of illness.", idiomatic: "The responsible offices, following the intent, investigated the matter; Yan Du was dismissed on grounds of illness." },
  { zh: "夏，五月，庚辰，尊博園匽貴人曰孝崇後，宮曰永樂；", literal: "In summer, the fifth month, on gengchen, the Lady of Boyuan Yan was honored as Empress Xiaochong, her palace named Yongle;", idiomatic: "In summer, in the fifth month, on gengchen day, the Lady of Boyuan Yan was honored as Empress Xiaochong, her palace named Yongle;" },
  { zh: "置太僕、少府以下，皆如長樂宮故事。", literal: "Grand Master of Transport, Privy Treasurer, and offices below were all established as at Changle Palace precedent.", idiomatic: "Grand Master of Transport, Privy Treasurer, and offices below were all established as at Changle Palace precedent." },
  { zh: "分巨鹿九縣為後湯沐邑。", literal: "Nine counties of Julu were divided as the empress's bath fief.", idiomatic: "Nine counties of Julu were divided as the empress's bath fief." },
  { zh: "秋，七月，梓潼山崩。", literal: "In autumn, the seventh month, Mount Zitong collapsed.", idiomatic: "In autumn, in the seventh month, Mount Zitong collapsed." },
  { zh: "春，正月朔，群臣朝賀，大將軍冀帶劍入省。", literal: "In spring, on the first day of the first month, when the ministers paid New Year homage, Grand General-in-Chief Ji entered the palace precinct wearing a sword.", idiomatic: "In spring, on the first day of the first month, when the ministers paid New Year homage, Grand General-in-Chief Liang Ji entered the palace precinct wearing a sword." },
  { zh: "尚書蜀郡張陵呵叱令出，敕羽林、虎賁奪劍。", literal: "Director of the Secretariat Zhang Ling of Shu commandery shouted and ordered him out, commanding the Forest Guards and Tiger Guards to seize the sword.", idiomatic: "Director of the Secretariat Zhang Ling of Shu commandery shouted and ordered him out, commanding the Forest Guards and Tiger Guards to seize the sword." },
  { zh: "冀跪謝，陵不應，即劾奏冀，請廷尉論罪。", literal: "Ji knelt to apologize; Ling did not respond and immediately impeached Ji, asking the Commandant of Justice to judge the offense.", idiomatic: "Liang Ji knelt to apologize; Zhang Ling did not respond and immediately impeached Ji, asking the Commandant of Justice to judge the offense." },
  { zh: "有詔，以一歲俸贖；", literal: "An edict ordered redemption by one year's salary;", idiomatic: "An edict ordered redemption by one year's salary;" },
  { zh: "百僚肅然。", literal: "the hundred officials were all solemn.", idiomatic: "the hundred officials were all solemn." },
  { zh: "河南尹不疑嘗舉陵孝廉，乃謂陵曰：「昔舉君，適所以自罰也！", literal: "Intendant of Henan Buyi had once recommended Ling as Filial and Incorrupt; he then said to Ling: \"In recommending you before, I was only punishing myself!", idiomatic: "Intendant of Henan Liang Buyi had once recommended Zhang Ling as Filial and Incorrupt; he then said to Ling, \"In recommending you before, I was only punishing myself!" },
  { zh: "」陵曰：「明府不以陵不肖，誤見擢序，今申公憲以報私恩！", literal: "\" Ling said: \"Your Excellency, not considering Ling unworthy, wrongly promoted me in rank—now I uphold public law to repay private favor!", idiomatic: "\" Zhang Ling said, \"Your Excellency, not considering Ling unworthy, wrongly promoted me in rank—now I uphold public law to repay private favor!" },
  { zh: "」不疑有愧色。", literal: "\" Buyi showed a look of shame.", idiomatic: "\" Liang Buyi showed a look of shame." },
  { zh: "癸酉，赦天下，改元。", literal: "On guiyou, amnesty was granted to all under Heaven and the reign era was changed.", idiomatic: "On guiyou day, amnesty was granted to all under Heaven and the reign era was changed." },
  { zh: "梁不疑好經書，喜待士，梁冀疾之，轉不疑為光祿勳；", literal: "Liang Buyi loved the classics and delighted in receiving scholars; Liang Ji resented this and transferred Buyi to Director of the Retainers;", idiomatic: "Liang Buyi loved the classics and delighted in receiving scholars. Liang Ji resented this and transferred Buyi to Director of the Retainers;" },
  { zh: "以其子胤為河南尹。", literal: "he made his son Yin Intendant of Henan.", idiomatic: "he made his son Liang Yin Intendant of Henan." },
  { zh: "胤年十六，客貌甚陋，不勝冠帶，道路見者莫不蚩笑。", literal: "Yin was sixteen, his appearance very homely, unable to bear cap and sash—passersby on the road all sneered.", idiomatic: "Liang Yin was sixteen, his appearance very homely, unable to bear cap and sash—passersby on the road all sneered." },
  { zh: "不疑自恥兄弟有隙，遂讓位歸第，與弟蒙閉門自守。", literal: "Buyi was ashamed that brothers had a rift and thereupon yielded his post and returned home, closing his gates with his brother Meng to keep to themselves.", idiomatic: "Liang Buyi was ashamed that brothers had a rift and thereupon yielded his post and returned home, closing his gates with his brother Meng to keep to themselves." },
  { zh: "冀不欲令與賓客交通，陰使人變服至門，記往來者。", literal: "Ji did not wish them to associate with guests and secretly sent men in disguise to their gates to record comings and goings.", idiomatic: "Liang Ji did not wish them to associate with guests and secretly sent men in disguise to their gates to record comings and goings." },
  { zh: "南郡太守馬融、江夏太守田明初除，守謁不疑；", literal: "Administrators of Nan commandery Ma Rong and Jiangxia Tian Ming had just been appointed and, on taking office, called to pay respects to Buyi;", idiomatic: "Administrators of Nan commandery Ma Rong and Jiangxia Tian Ming had just been appointed and, on taking office, called to pay respects to Liang Buyi;" },
  { zh: "冀諷有司奏融在郡貪濁，及以它事陷明，皆髡笞徙朔方。", literal: "Ji prompted the responsible offices to memorialize that Rong was greedy and corrupt in the commandery and to trap Ming on other charges—both were shaved, flogged, and banished to Shuofang.", idiomatic: "Liang Ji prompted the responsible offices to memorialize that Ma Rong was greedy and corrupt in the commandery and to trap Tian Ming on other charges—both were shaved, flogged, and banished to Shuofang." },
  { zh: "融自刺不殊，明遂死於路。", literal: "Rong stabbed himself but did not die; Ming then died on the road.", idiomatic: "Ma Rong stabbed himself but did not die; Tian Ming then died on the road." },
  { zh: "夏，四月，己丑，上微行，幸河南尹梁胤府捨。", literal: "In summer, the fourth month, on jichou, the emperor made a secret excursion and visited the residence of Intendant of Henan Liang Yin.", idiomatic: "In summer, in the fourth month, on jichou day, the emperor made a secret excursion and visited the residence of Intendant of Henan Liang Yin." },
  { zh: "是日，大風拔樹，晝昏。", literal: "That day a great wind uprooted trees and daylight turned dim.", idiomatic: "That day a great wind uprooted trees and daylight turned dim." },
  { zh: "尚書楊秉上疏曰：「臣聞天下言語，以災異譴告。", literal: "Director of the Secretariat Yang Bing submitted a memorial, saying: \"Your servant has heard that speech under Heaven uses prodigies and anomalies to warn and reprove.", idiomatic: "Director of the Secretariat Yang Bing submitted a memorial, saying, \"Your servant has heard that speech under Heaven uses prodigies and anomalies to warn and reprove." },
  { zh: "王者至尊，出入有常，警蹕而行，靜室而止，自非郊廟之事，則鑾旗不駕。", literal: "The king's position is supreme—going out and coming in have constants, proceeding with guards and halts, stopping in a quiet chamber; unless for suburban or temple affairs, the imperial banners are not driven.", idiomatic: "The king's position is supreme—going out and coming in have constants, proceeding with guards and halts, stopping in a quiet chamber. Unless for suburban or temple affairs, the imperial banners are not driven." },
  { zh: "故諸侯入諸臣之家，《春秋》尚列其誡；", literal: "Therefore when feudal lords entered ministers' houses, the Spring and Autumn still listed its admonition;", idiomatic: "Therefore when feudal lords entered ministers' houses, the Spring and Autumn still listed its admonition;" },
  { zh: "況於以先王法服而私出槃游，降亂尊卑，等威無序，侍衛守空宮，璽紱委女妾！", literal: "how much more when, in the former kings' ritual garb, one privately goes out roaming in disorder, lowering and confusing honor and baseness, rank and awe without order—guards guarding an empty palace, seals and ribbons left to concubines!", idiomatic: "how much more when, in the former kings' ritual garb, one privately goes out roaming in disorder, lowering and confusing honor and baseness, rank and awe without order—guards guarding an empty palace, seals and ribbons left to concubines!" },
  { zh: "設有非常之變，任章之謀，上負先帝，下悔靡及！", literal: "If there were an extraordinary change or a plot like Ren Zhang's, above you would fail the former emperor, below regret would never catch up!", idiomatic: "If there were an extraordinary change or a plot like Ren Zhang's, above you would fail the former emperor, below regret would never catch up!" },
  { zh: "」帝不納。", literal: "\" The emperor did not accept this.", idiomatic: "\" The emperor did not accept this." },
  { zh: "秉，震之子也。", literal: "Bing was the son of Zhen.", idiomatic: "Yang Bing was the son of Yang Zhen." },
  { zh: "京師旱，任城、梁國饑，民相食。", literal: "The capital region suffered drought; Rencheng and Liang kingdom had famine, and the people ate one another.", idiomatic: "The capital region suffered drought; Rencheng and Liang kingdom had famine, and the people ate one another." },
  { zh: "司徒張歆罷，以光祿勳吳雄為司徒。", literal: "Minister of Education Zhang Xin was dismissed; Director of the Retainers Wu Xiong was made Minister of Education.", idiomatic: "Minister of Education Zhang Xin was dismissed; Director of the Retainers Wu Xiong was made Minister of Education." },
  { zh: "北匈奴呼銜王寇伊吾，敗伊吾司馬毛愷，攻伊吾屯城。", literal: "The Northern Xiongnu Huxian king raided Yiwu, defeated Yiwu Major Mao Kai, and attacked the Yiwu garrison city.", idiomatic: "The Northern Xiongnu Huxian king raided Yiwu, defeated Yiwu Major Mao Kai, and attacked the Yiwu garrison city." },
  { zh: "詔敦煌太守馬達將兵救之；", literal: "An edict ordered Administrator of Dunhuang Ma Da to lead troops to rescue them;", idiomatic: "An edict ordered Administrator of Dunhuang Ma Da to lead troops to rescue them;" },
  { zh: "至蒲類海，呼衍王引去。", literal: "when they reached Lake Pulei, the Huyan king withdrew.", idiomatic: "when they reached Lake Pulei, the Huyan king withdrew." },
  { zh: "秋，七月，武陵蠻反。", literal: "In autumn, the seventh month, the Wuling Man rebelled.", idiomatic: "In autumn, in the seventh month, the Wuling Man rebelled." },
  { zh: "冬，十月，司空胡廣致仕。", literal: "In winter, the tenth month, Minister of Works Hu Guang retired from office.", idiomatic: "In winter, in the tenth month, Minister of Works Hu Guang retired from office." },
  { zh: "十一月，辛巳，京師地震。", literal: "In the eleventh month, on xinsi, the capital region had an earthquake.", idiomatic: "In the eleventh month, on xinsi day, the capital region had an earthquake." },
  { zh: "詔百官舉獨行之士。", literal: "An edict ordered the hundred officials to recommend men of exceptional conduct.", idiomatic: "An edict ordered the hundred officials to recommend men of exceptional conduct." },
  { zh: "涿郡舉崔寔，詣公車，稱病，不對策；", literal: "Zhuo commandery recommended Cui Shi; he went to the Imperial Coach Office, claimed illness, and did not answer the policy questions;", idiomatic: "Zhuo commandery recommended Cui Shi; he went to the Imperial Coach Office, claimed illness, and did not answer the policy questions;" },
  { zh: "退而論世事，名曰《政論》。", literal: "withdrawing, he discussed affairs of the age in a work titled \"Discourse on Government.\"", idiomatic: "withdrawing, he discussed affairs of the age in a work titled \"Discourse on Government.\"" },
  { zh: "其辭曰：「凡天下所以不治者，常由人主承平日久，俗漸敝而不悟，政浸衰而不改，習亂安危，怢不自睹。", literal: "Its words say: \"In general, the reason all under Heaven is not well governed is usually that the ruler enjoys long peace, customs gradually decay without awareness, government slowly declines without reform, accustomed to disorder they take danger for safety and do not see themselves.", idiomatic: "Its words say, \"In general, the reason all under Heaven is not well governed is usually that the ruler enjoys long peace, customs gradually decay without awareness, government slowly declines without reform, accustomed to disorder they take danger for safety and do not see themselves." },
  { zh: "或荒耽耆欲，不恤萬機；", literal: "Some are dissolute and sunk in desires, uncaring for the myriad affairs of state;", idiomatic: "Some are dissolute and sunk in desires, uncaring for the myriad affairs of state;" },
  { zh: "或耳蔽箴誨，厭偽忽真；", literal: "some have ears blocked to admonition, weary of the false and neglecting the true;", idiomatic: "some have ears blocked to admonition, weary of the false and neglecting the true;" },
  { zh: "或猶豫歧路，莫適所以；", literal: "some hesitate at crossroads, not knowing what to follow;", idiomatic: "some hesitate at crossroads, not knowing what to follow;" },
  { zh: "或見信之佐，括囊守祿；", literal: "some trusted assistants tie the bag and guard salary.", idiomatic: "some trusted assistants tie the bag shut and guard their salaries." },
  { zh: "或疏遠之臣，言以賤廢。", literal: "Or distant and estranged ministers spoke and were dismissed for being base.", idiomatic: "Or distant and estranged ministers spoke up and were dismissed for being base." },
  { zh: "是以王綱縱弛於上，智士郁伊于下。", literal: "Thus the royal net was slack above and wise men depressed below.", idiomatic: "Thus the royal net was slack above and wise men were depressed below." },
  { zh: "悲夫！", literal: "Alas!", idiomatic: "Alas!" },
  { zh: "自漢興以來，三百五十餘歲矣，政令垢玩，上下怠懈，百姓囂然，鹹復思中興之救矣！", literal: "Since the Han rose, more than three hundred fifty years have passed; government orders are filthy and neglected, above and below are slack and remiss, the common people clamor, and all again long for the remedy of restoration!", idiomatic: "Since the Han rose, more than three hundred fifty years have passed. Government orders are filthy and neglected, above and below are slack and remiss, the common people clamor, and all again long for the remedy of restoration!" },
  { zh: "且濟時拯世之術，在於補衣定決壞，枝拄邪傾，隨形裁割，要措斯世於安寧之域而已。", literal: "Moreover the art of aiding the age and saving the world lies in patching clothes and fixing broken seams, propping what tilts awry, cutting according to the form, and simply placing this generation in the realm of peace and quiet.", idiomatic: "Moreover the art of aiding the age and saving the world lies in patching clothes and fixing broken seams, propping what tilts awry, cutting according to the form, and simply placing this generation in the realm of peace and quiet." },
  { zh: "故聖人執權，遭時定制，步驟之差，各有雲設，不強人以不能，背急切而慕所聞也。", literal: "Therefore the sage holds power, meets the time and fixes institutions; differences in steps each have their cloud-like setting, not forcing people with what they cannot do, turning the back on urgent needs while admiring what one has heard.", idiomatic: "Therefore the sage holds power, meets the time and fixes institutions. Differences in steps each have their cloud-like setting. He does not force people with what they cannot do or turn his back on urgent needs while admiring what he has heard." },
  { zh: "蓋孔子對葉公以來遠，哀公以臨人，景公以節禮，非其不同，所急異務也。", literal: "Confucius answered Duke Ye with \"come from afar,\" Duke Ai with \"oversee the people,\" and Duke Jing with \"restrain ritual\"—not that he was different, but what was urgent differed in task.", idiomatic: "Confucius answered Duke Ye with \"come from afar,\" Duke Ai with \"oversee the people,\" and Duke Jing with \"restrain ritual\"—not that he was inconsistent, but what was urgent differed in each case." },
  { zh: "俗人拘文牽占，不達權制，奇偉所聞，簡忽所見，烏可與論國家之大事哉！", literal: "Vulgar men cling to texts and drag in prognostication, not reaching expedient institutions; they marvel at what they hear and slight what they see—how can one discuss great affairs of state with them!", idiomatic: "Vulgar men cling to texts and drag in prognostication, not reaching expedient institutions. They marvel at what they hear and slight what they see—how can one discuss great affairs of state with them!" },
  { zh: "故言事者雖合聖德，輒見掎奪。", literal: "Therefore those who speak on affairs, though matching sage virtue, are at once seized and wrested away.", idiomatic: "Therefore those who speak on affairs, though matching sage virtue, are at once seized and wrested away." },
  { zh: "何者？", literal: "Why?", idiomatic: "Why?" },
  { zh: "其頑士暗於時權，安習所見，不知樂成，況可慮始，苟雲率由舊章而已。", literal: "The obstinate scholars are dark to timely power, content with what they are used to seeing, not knowing to rejoice in accomplishment—how much less to consider the beginning—and only say \"follow the old statutes\" and nothing more.", idiomatic: "The obstinate scholars are dark to timely power, content with what they are used to seeing, not knowing to rejoice in accomplishment—how much less to consider the beginning—and only say \"follow the old statutes\" and nothing more." },
  { zh: "其達者或矜名妒能，恥策非己，舞筆奮辭以破其義。", literal: "The accomplished sometimes prize their names and envy ability, ashamed that strategies are not their own, waving the brush and rousing words to break others' arguments.", idiomatic: "The accomplished sometimes prize their names and envy ability, ashamed that strategies are not their own, waving the brush and rousing words to break others' arguments." },
  { zh: "寡不勝眾，遂見擯棄，雖稷、契復存，猶將困焉。", literal: "The few cannot overcome the many; they are then cast aside. Even if Hou Ji and Xie lived again, they would still be trapped.", idiomatic: "The few cannot overcome the many; they are then cast aside. Even if Hou Ji and Xie lived again, they would still be trapped." },
  { zh: "斯賢智之論所以常憤郁而不伸者也。", literal: "This is why the discourse of the worthy and wise is constantly angry and depressed yet cannot extend itself.", idiomatic: "This is why the discourse of the worthy and wise is constantly angry and depressed yet cannot extend itself." },
  { zh: "「凡為天下者，自非上德，嚴之則治，寬之則亂。", literal: "\" For all who hold the realm, unless they have supreme virtue, if strict then governed, if lenient then chaotic.", idiomatic: "\" For all who hold the realm, unless they have supreme virtue, if strict then governed, if lenient then chaotic." },
  { zh: "何以明其然也？", literal: "How is this shown to be so?", idiomatic: "How is this shown to be so?" },
  { zh: "近孝宣皇帝明於君人之道，審於為政之理，故嚴刑峻法，破奸軌之膽，海內清肅，天下密如，逄計見效，優於孝文。", literal: "Recently Emperor Xuan was clear in the Way of ruling men and discerning in the principle of governing, and so with severe punishments and stern laws broke the courage of wicked paths; within the seas all was pure and solemn, all under Heaven tight as a mesh; every measure showed effect, superior to Emperor Wen.", idiomatic: "Recently Emperor Xuan was clear in the Way of ruling men and discerning in the principle of governing, and so with severe punishments and stern laws broke the courage of wicked paths. Within the seas all was pure and solemn, all under Heaven tight as a mesh. Every measure showed effect, superior to Emperor Wen." },
  { zh: "及元帝即位，多行寬政，卒以墮損，威權始奪，遂為漢室基禍之主。", literal: "When Emperor Yuan ascended the throne he mostly practiced lenient government, and in the end thereby declined and was damaged; authority was first seized away, and he became the sovereign who laid the foundation of disaster for the Han house.", idiomatic: "When Emperor Yuan ascended the throne he mostly practiced lenient government, and in the end thereby declined and was damaged. Authority was first seized away, and he became the sovereign who laid the foundation of disaster for the Han house." },
  { zh: "政道得失，於斯可鑒。", literal: "The gain and loss of the way of government may here be taken as a mirror.", idiomatic: "The gain and loss of the way of government may here be taken as a mirror." },
  { zh: "昔孔子作《春秋》，褒齊桓，懿晉文，歎管仲之功，夫豈不美文、武之道哉？", literal: "Formerly when Confucius composed the \"Spring and Autumn,\" he praised Duke Huan of Qi, commended Duke Wen of Jin, and sighed over Guan Zhong's achievement—did he not love the Way of Wen and Wu?", idiomatic: "Formerly when Confucius composed the \"Spring and Autumn,\" he praised Duke Huan of Qi, commended Duke Wen of Jin, and sighed over Guan Zhong's achievement—did he not love the Way of Wen and Wu?" },
  { zh: "誠達權救敝之理也。", literal: "Truly it was reaching expedient power and saving what was worn.", idiomatic: "Truly it was reaching expedient power and saving what was worn." },
  { zh: "故聖人能與世推移，而俗士苦不知變，以為結繩之約，可復治亂秦之緒；", literal: "Therefore the sage can shift with the age, while vulgar scholars bitterly do not know change, thinking the covenant of knotted cords can again govern the threads of Qin's chaos;", idiomatic: "Therefore the sage can shift with the age, while vulgar scholars bitterly do not know change, thinking the covenant of knotted cords can again govern the threads of Qin's chaos;" },
  { zh: "干戚之舞，足以解平城之圍。", literal: "the shield-and-axe dance is enough to relieve the siege of Pingcheng.", idiomatic: "the shield-and-axe dance is enough to relieve the siege of Pingcheng." },
  { zh: "夫熊經鳥伸，雖延歷之術，非傷寒之理；", literal: "Bear-stretching and bird-bending, though arts of prolonging life, are not the principle for cold-damage illness;", idiomatic: "Bear-stretching and bird-bending, though arts of prolonging life, are not the principle for cold-damage illness;" },
  { zh: "呼吸吐納，雖度紀之道，非續骨之膏。", literal: "breathing in and breathing out, though the Way of passing the eras, is not salve for mending bone.", idiomatic: "breathing in and breathing out, though the Way of passing the eras, is not salve for mending bone." },
  { zh: "蓋為國之法，有似治身，平則致養，疾則攻焉。", literal: "The law for governing a state is like treating the body: when peaceful then nurture, when ill then attack.", idiomatic: "The law for governing a state is like treating the body: when peaceful then nurture, when ill then attack." },
  { zh: "夫刑罰者，治亂之藥石也；", literal: "Punishments and penalties are the medicine-stone for order and chaos;", idiomatic: "Punishments and penalties are the medicine-stone for order and chaos;" },
  { zh: "德教者，興平之粱肉也。", literal: "virtue and instruction are the fine grain and meat for flourishing peace.", idiomatic: "virtue and instruction are the fine grain and meat for flourishing peace." },
  { zh: "夫以德教除殘，是以粱肉治疾也；", literal: "To use virtue and instruction to remove violence is to use fine food to treat illness;", idiomatic: "To use virtue and instruction to remove violence is to use fine food to treat illness;" },
  { zh: "以刑罰治平，是以藥石供養也。", literal: "to use punishments and penalties to govern peace is to use medicine-stone for nourishment.", idiomatic: "to use punishments and penalties to govern peace is to use medicine-stone for nourishment." },
  { zh: "方今承百王之敝，值厄運之會，自數世以來，政多恩貸，馭委其轡。", literal: "Now we inherit the worn state of a hundred kings and meet the conjunction of ill fortune; since several generations government has mostly been lenient pardon, and the driver has let go the reins.", idiomatic: "Now we inherit the worn state of a hundred kings and meet the conjunction of ill fortune. Since several generations government has mostly been lenient pardon, and the driver has let go the reins." },
  { zh: "馬駘其銜，四牡橫奔，皇路險傾，方將拑勒鞬輈以救之，豈暇鳴和鑾，請節奏哉！", literal: "The horses chew their bits, the four stallions run wild across, the imperial road is perilously tilted—just about to clamp the reins, tighten the bridle, and steer to save it; how is there leisure to sound the harmonious bells and ask for measured pace!", idiomatic: "The horses chew their bits, the four stallions run wild across, the imperial road is perilously tilted—just about to clamp the reins, tighten the bridle, and steer to save it. How is there leisure to sound the harmonious bells and ask for measured pace!" },
  { zh: "昔文帝雖除肉刑，當斬右趾者棄市，笞者往往至死。", literal: "Formerly Emperor Wen though he abolished flesh punishments, yet those who should have had the right foot cut were exposed in the market, and those flogged often died.", idiomatic: "Formerly Emperor Wen though he abolished flesh punishments, yet those who should have had the right foot cut were exposed in the market, and those flogged often died." },
  { zh: "是文帝以嚴致平，非以寬致平也。", literal: "Thus Emperor Wen brought peace through severity, not through lenience.", idiomatic: "Thus Emperor Wen brought peace through severity, not through lenience." },
  { zh: "」寔，瑗之子也。", literal: "\" Shi was the son of Yuan.", idiomatic: "\" Shi was the son of Yuan." },
  { zh: "山陽仲長統嘗見其書，歎曰：「凡為人主，宜寫一通，置之坐側。", literal: "Zhongchang Tong of Shanyang once saw his book and sighed, saying: \"For every ruler it is fitting to copy one scroll and place it beside his seat.", idiomatic: "Zhongchang Tong of Shanyang once saw his book and sighed, saying, \"For every ruler it is fitting to copy one scroll and place it beside his seat." },
  { zh: "══臣光曰：漢家之法已嚴矣，而崔寔猶病其寬，何哉？", literal: "══ Master Guang said: Han law is already severe, yet Cui Shi still complains it is lenient—why?", idiomatic: "══ Master Guang said: Han law is already severe, yet Cui Shi still complains it is lenient—why?" },
  { zh: "蓋衰世之君，率多柔懦，凡愚之佐，唯知姑息，是以權幸之臣有罪不坐，豪猾之民犯法不誅；", literal: "Generally rulers of a declining age are mostly soft and weak; foolish assistants know only indulgence—thus favored ministers guilty yet not punished, fierce and cunning commoners breaking law yet not executed;", idiomatic: "Generally rulers of a declining age are mostly soft and weak, and foolish assistants know only indulgence. Thus favored ministers are guilty yet not punished, and fierce and cunning commoners break the law yet are not executed;" },
  { zh: "仁恩所施，止於目前；", literal: "benevolence and grace extend only to what is before the eyes;", idiomatic: "benevolence and grace extend only to what is before the eyes;" },
  { zh: "奸宄得志，紀綱不立。", literal: "traitors and villains get their will; the net of law is not established.", idiomatic: "traitors and villains get their will, and the net of law is not established." },
  { zh: "故崔寔之論，以矯一時之枉，非百世之通義也。", literal: "Therefore Cui Shi's discourse was to correct the warp of one time, not the universal meaning for a hundred generations.", idiomatic: "Therefore Cui Shi's discourse was to correct the warp of one time, not the universal meaning for a hundred generations." },
  { zh: "孔子曰：「政寬則民慢，慢則糾之以猛；", literal: "Confucius said: \"When government is lenient the people are slack; when slack then correct them with severity;", idiomatic: "Confucius said, \"When government is lenient the people are slack; when slack then correct them with severity;" },
  { zh: "猛則民殘，殘則施之以寬。", literal: "when severe the people are harmed; when harmed then apply lenience to them.", idiomatic: "when severe the people are harmed; when harmed then apply lenience to them." },
  { zh: "寬以濟猛，猛以濟寬，政是以和。", literal: "Lenience to aid severity, severity to aid lenience—thus government is harmonious.", idiomatic: "Lenience to aid severity, severity to aid lenience—thus government is harmonious." },
  { zh: "」斯不易之常道矣。", literal: "\" This is the constant Way that does not change.", idiomatic: "\" This is the constant Way that does not change." },
  { zh: "閏月，庚午，任城節王崇薨；", literal: "In the intercalary month, on gengwu day, Exemplary King Chong of Rencheng died;", idiomatic: "In the intercalary month, on gengwu day, Exemplary King Chong of Rencheng died;" },
  { zh: "無子，國絕。", literal: "He had no son; the state was extinguished.", idiomatic: "He had no son, and the state was extinguished." },
  { zh: "以太常黃瓊為司空。", literal: "Made Minister of Ceremonies Huang Qiong Minister of Works.", idiomatic: "Minister of Ceremonies Huang Qiong was made Minister of Works." },
  { zh: "帝欲褒崇梁冀，使中朝二千石以上會議其禮。", literal: "The emperor wished to honor and exalt Liang Ji and had central-court officials of two thousand bushels and above assemble to deliberate his rites.", idiomatic: "The emperor wished to honor and exalt Liang Ji and had central-court officials of two thousand bushels and above assemble to deliberate his rites." },
  { zh: "特進胡廣、太常羊浦、司隸校尉祝恬、太中大夫邊韶等咸稱冀之勳德宜比周公，錫之山川、土田、附庸。", literal: "Special Advance Hu Guang, Minister of Ceremonies Yang Pu, Colonel of the Metropolitan Area Zhu Tian, Grand Master of the Palace Bian Shao, and others all said Ji's merit and virtue should be compared to the Duke of Zhou, bestowing mountains and rivers, land fields, and attached states.", idiomatic: "Special Advance Hu Guang, Minister of Ceremonies Yang Pu, Colonel of the Metropolitan Area Zhu Tian, Grand Master of the Palace Bian Shao, and others all said Ji's merit and virtue should be compared to the Duke of Zhou, bestowing mountains and rivers, land fields, and attached states." },
  { zh: "黃瓊獨曰：「冀前以親迎之勞，增邑成三千戶；", literal: "Huang Qiong alone said: \"Ji earlier for the labor of welcoming the bride in person had his fief increased to three thousand households;", idiomatic: "Huang Qiong alone said, \"Ji earlier for the labor of welcoming the bride in person had his fief increased to three thousand households;" },
  { zh: "又其子胤亦加封賞。", literal: "also his son Yin received added enfeoffment and reward.", idiomatic: "also his son Yin received added enfeoffment and reward." },
  { zh: "今諸侯以戶邑為制，不以裡數為限，冀可比鄧禹，合食四縣。", literal: "Now feudal lords are regulated by household fiefs, not limited by village count—Ji may be compared to Deng Yu and receive revenue from four counties together.", idiomatic: "Now feudal lords are regulated by household fiefs, not limited by village count. Ji may be compared to Deng Yu and receive revenue from four counties together." },
  { zh: "」朝廷從之。", literal: "\" The court followed this.", idiomatic: "\" The court followed this." },
  { zh: "於是有司奏：「冀入朝不趨，劍履上殿，謁贊不名，禮儀比蕭何；", literal: "Thereupon the responsible officials memorialized: \"Ji on entering court need not hasten, may wear sword and shoes in the hall, and at audience need not have his name announced—rites like Xiao He;", idiomatic: "Thereupon the responsible officials memorialized, \"Ji on entering court need not hasten, may wear sword and shoes in the hall, and at audience need not have his name announced—rites like Xiao He;" },
  { zh: "悉以定陶、陽成餘戶增封為四縣，比鄧禹；", literal: "all remaining households of Dingtao and Yangcheng added to his fief as four counties, like Deng Yu;", idiomatic: "all remaining households of Dingtao and Yangcheng added to his fief as four counties, like Deng Yu;" },
  { zh: "賞賜金錢、奴婢、彩帛、車馬、衣服、甲第，比霍光；", literal: "bestowals of cash, slaves, silks, carriages, horses, robes, and fine mansions, like Huo Guang;", idiomatic: "bestowals of cash, slaves, silks, carriages, horses, robes, and fine mansions, like Huo Guang;" },
  { zh: "以殊元勳。", literal: "to distinguish extraordinary merit.", idiomatic: "to distinguish extraordinary merit." },
  { zh: "每朝會，與三會絕席。", literal: "At each court assembly he had a separate seat apart from the Three Excellencies.", idiomatic: "At each court assembly he had a separate seat apart from the Three Excellencies." },
  { zh: "十日一入，平尚書事。", literal: "Once every ten days he entered and settled Secretariat affairs.", idiomatic: "Once every ten days he entered and settled Secretariat affairs." },
  { zh: "宣佈天下，為萬世法。", literal: "Proclaim throughout the realm as law for ten thousand generations.", idiomatic: "Proclaim throughout the realm as law for ten thousand generations." },
  { zh: "」冀猶以所奏禮簿，意不悅。", literal: "\" Ji still because of the memorialized ritual register was displeased in mind.", idiomatic: "\" Ji was still displeased with the memorialized ritual register." },
  { zh: "春，正月，西域長史王敬為於窴所殺。", literal: "In spring, the first month, Chief Clerk of the Western Regions Wang Jing was killed by Yutian.", idiomatic: "In spring, in the first month, Chief Clerk of the Western Regions Wang Jing was killed by Yutian." },
  { zh: "初，西域長史趙評在於窴，病癰死。", literal: "Initially Chief Clerk Zhao Ping was in Yutian and died of an abscess illness.", idiomatic: "Initially Chief Clerk Zhao Ping was in Yutian and died of an abscess illness." },
  { zh: "評子迎喪，道經拘彌。", literal: "Ping's son met the funeral procession, passing by Jimi.", idiomatic: "Ping's son met the funeral procession, passing by Jimi." },
  { zh: "拘彌王成國與於窴王建素有隙，謂評子曰：「於窴王令胡醫持毒藥著創中，故致死耳！", literal: "King Chengguo of Jimi and King Jian of Yutian had long had a rift; he told Ping's son: \"The king of Yutian had a barbarian physician apply poison medicine in the wound, and so caused death!", idiomatic: "King Chengguo of Jimi and King Jian of Yutian had long had a rift. He told Ping's son, \"The king of Yutian had a barbarian physician apply poison medicine in the wound and so caused death!" },
  { zh: "」評子信之，還，以告敦煌太守馬達。", literal: "\" Ping's son believed it; on returning he reported it to Administrator of Dunhuang Ma Da.", idiomatic: "\" Ping's son believed it. On returning he reported it to Administrator of Dunhuang Ma Da." },
  { zh: "會敬代為長史，馬達令敬隱核於窴事。", literal: "It happened that Jing replaced him as chief clerk; Ma Da ordered Jing to investigate secretly the Yutian affair.", idiomatic: "It happened that Jing replaced him as chief clerk. Ma Da ordered Jing to investigate secretly the Yutian affair." },
  { zh: "敬先過拘彌，成國復說雲。", literal: "Jing first passed Jimi; Chengguo again spoke, saying:", idiomatic: "Jing first passed Jimi. Chengguo again spoke, saying," },
  { zh: "「於窴國人欲以我為王；", literal: "\" The people of Yutian wish to make me king;", idiomatic: "\" The people of Yutian wish to make me king;" },
  { zh: "今可因此罪誅建，於窴必服矣。", literal: "now we can use this crime to execute Jian, and Yutian will surely submit.", idiomatic: "now we can use this crime to execute Jian, and Yutian will surely submit." },
  { zh: "」敬貪立功名，前到於窴，設供具，請建而陰圖之。", literal: "\" Jing, greedy to establish merit and fame, went ahead to Yutian, set out provisions, invited Jian, and secretly plotted against him.", idiomatic: "\" Jing, greedy to establish merit and fame, went ahead to Yutian, set out provisions, invited Jian, and secretly plotted against him." },
  { zh: "或以敬謀告建，建不信，曰：「我無罪，王長史何為欲殺我？", literal: "Someone reported Jing's plot to Jian; Jian did not believe it and said: \"I have no crime—why would the king's chief clerk wish to kill me?", idiomatic: "Someone reported Jing's plot to Jian. Jian did not believe it and said, \"I have no crime—why would the king's chief clerk wish to kill me?" },
  { zh: "」旦日，建從官屬數十人詣敬，坐定，建起行酒，敬叱左右執之。", literal: "\" Next day Jian with several tens of his officials and attendants came to Jing; when seated Jian rose to offer wine; Jing shouted to attendants left and right to seize him.", idiomatic: "\" The next day Jian with several tens of his officials and attendants came to Jing. When seated, Jian rose to offer wine. Jing shouted to attendants left and right to seize him." },
  { zh: "吏士並無殺建意，官屬悉得突走。", literal: "The clerks and soldiers all had no intent to kill Jian; the officials and attendants all broke out and fled.", idiomatic: "The clerks and soldiers all had no intent to kill Jian, and the officials and attendants all broke out and fled." },
  { zh: "時成國主簿秦牧隨敬在會，持刀出，曰：「大事已定，何為復疑！", literal: "At the time Registrar Qin Mu of Chengguo followed Jing at the meeting, drew a blade, came forward, and said: \"The great affair is already settled—why still doubt!", idiomatic: "At the time Registrar Qin Mu of Chengguo followed Jing at the meeting, drew a blade, came forward, and said, \"The great affair is already settled—why still doubt!" },
  { zh: "」即前斬建。", literal: "\" He at once went forward and beheaded Jian.", idiomatic: "\" He at once went forward and beheaded Jian." },
  { zh: "於窴侯、將輸僰等遂會兵攻敬，敬持建頭上樓宣告曰：「天子使我誅建耳！", literal: "The marquis of Yutian, the general Shubi, and others thereupon gathered troops and attacked Jing. Jing held Jian's head, went up a tower, and proclaimed: \"The Son of Heaven sent me to execute Jian!", idiomatic: "The marquis of Yutian, the general Shubi, and others thereupon gathered troops and attacked Jing. Jing held Jian's head, went up a tower, and proclaimed, \"The Son of Heaven sent me to execute Jian!" },
  { zh: "」輸僰不聽，上樓斬敬，懸首於市。", literal: "\" Shubi would not listen, went up the tower and beheaded Jing, and hung the head in the market.", idiomatic: "\" Shubi would not listen, went up the tower and beheaded Jing, and hung the head in the market." },
  { zh: "輸僰自立為王；", literal: "Shubi installed himself as king;", idiomatic: "Shubi installed himself as king;" },
  { zh: "國人殺之，而立建子安國。", literal: "the people of the state killed him and established Jian's son Anguo.", idiomatic: "the people of the state killed him and established Jian's son Anguo." },
  { zh: "馬達聞王敬死，欲將諸郡兵出塞擊於窴；", literal: "Ma Da on hearing Wang Jing had died wished to lead commandery troops beyond the passes to strike Yutian;", idiomatic: "Ma Da on hearing Wang Jing had died wished to lead commandery troops beyond the passes to strike Yutian;" },
  { zh: "帝不聽，征達還，而以宋亮代為敦煌太守。", literal: "the emperor would not listen, summoned Da back, and made Song Liang Administrator of Dunhuang in his place.", idiomatic: "the emperor would not listen, summoned Ma Da back, and made Song Liang Administrator of Dunhuang in his place." },
  { zh: "亮到，開募於窴，令自斬輸僰；", literal: "When Liang arrived he opened recruitment in Yutian and ordered them to behead Shubi themselves;", idiomatic: "When Liang arrived he opened recruitment in Yutian and ordered them to behead Shubi themselves;" },
  { zh: "時輸僰死已經月，乃斷死人頭送敦煌而不言其狀，亮後知其詐，而竟不能討也。", literal: "at the time Shubi had been dead more than a month; they then cut off a dead man's head and sent it to Dunhuang without stating the facts. Liang later knew of the fraud yet in the end could not punish them.", idiomatic: "At the time Shubi had been dead more than a month. They then cut off a dead man's head and sent it to Dunhuang without stating the facts. Liang later knew of the fraud yet in the end could not punish them." },
  { zh: "丙辰，京師地震。", literal: "On bingchen day the capital region quaked.", idiomatic: "On bingchen day the capital region quaked." },
  { zh: "夏，四月，甲辰，孝崇皇后匽氏崩；", literal: "In summer, the fourth month, on jiachen day, Empress Xiaochong Lady Yan died;", idiomatic: "In summer, in the fourth month, on jiachen day, Empress Xiaochong Lady Yan died;" },
  { zh: "以帝弟平原王石為喪主，斂送制度比恭懷皇后。", literal: "the emperor's younger brother, King Shi of Pingyuan, was made chief mourner; encoffining and escort rites matched Empress Gonghuai.", idiomatic: "the emperor's younger brother, King Shi of Pingyuan, was made chief mourner. Encoffining and escort rites matched Empress Gonghuai." },
  { zh: "五月，辛卯，葬於博陵。", literal: "In the fifth month, on xinmao day, she was buried at Boling.", idiomatic: "In the fifth month, on xinmao day, she was buried at Boling." },
  { zh: "秋，七月，庚辰，日有食之。", literal: "In autumn, the seventh month, on gengchen day, there was a solar eclipse.", idiomatic: "In autumn, in the seventh month, on gengchen day, there was a solar eclipse." },
  { zh: "冬，十月，乙亥，京師地震。", literal: "In winter, the tenth month, on yihai day, the capital region quaked.", idiomatic: "In winter, in the tenth month, on yihai day, the capital region quaked." },
  { zh: "十一月，司空黃瓊免。", literal: "In the eleventh month, Minister of Works Huang Qiong was dismissed.", idiomatic: "In the eleventh month, Minister of Works Huang Qiong was dismissed." },
  { zh: "十二月，以特進趙戒為司空。", literal: "In the twelfth month, made Special Advance Zhao Jie Minister of Works.", idiomatic: "In the twelfth month, Special Advance Zhao Jie was made Minister of Works." },
  { zh: "春，三月，丁亥，帝幸鴻池。", literal: "In spring, the third month, on dinghai day, the emperor visited Hong Pond.", idiomatic: "In spring, in the third month, on dinghai day, the emperor visited Hong Pond." },
  { zh: "夏，四月，丙申，赦天下，改元。", literal: "In summer, the fourth month, on bingshen day, amnestied the realm and changed the reign title.", idiomatic: "In summer, in the fourth month, on bingshen day, the realm was amnestied and the reign title was changed." },
  { zh: "丁酉，濟南悼王廣薨；", literal: "On dingyou day, Lamented King Guang of Jinan died;", idiomatic: "On dingyou day, Lamented King Guang of Jinan died;" },
  { zh: "無子，國除。", literal: "He had no son; the state was abolished.", idiomatic: "He had no son, and the state was abolished." },
  { zh: "秋，七月，郡、國三十二蝗，河水溢。", literal: "In autumn, the seventh month, thirty-two commanderies and states suffered locusts and the Yellow River overflowed.", idiomatic: "In autumn, in the seventh month, thirty-two commanderies and states suffered locusts and the Yellow River overflowed." },
  { zh: "百姓饑窮流冗者數十萬戶，冀州尤甚。", literal: "Common people starving and destitute, drifting and scattered, numbered several hundred thousand households; Ji province was especially severe.", idiomatic: "Common people starving and destitute, drifting and scattered, numbered several hundred thousand households. Ji province was especially severe." },
  { zh: "詔以侍御史朱穆為冀州刺史。", literal: "An edict made Attending Imperial Clerk Zhu Mu Governor of Ji.", idiomatic: "An edict made Attending Imperial Clerk Zhu Mu Governor of Ji." },
  { zh: "冀部令長聞穆濟河，解印綬去者四十餘人。", literal: "Magistrates and chiefs of the Ji region, hearing that Mu was crossing the river, resigned their seals and ribbons—more than forty men.", idiomatic: "More than forty magistrates and chiefs of the Ji region, hearing that Mu was crossing the river, resigned their seals and ribbons and left." },
  { zh: "及到，奏劾諸郡貪污者，有至自殺，或死獄中。", literal: "When he arrived, he memorialized impeaching the corrupt in the various commanderies; some went so far as to commit suicide, others died in prison.", idiomatic: "When he arrived, he memorialized impeaching the corrupt in the various commanderies. Some committed suicide, and others died in prison." },
  { zh: "宦者趙忠喪父，歸葬安平，僭為玉匣；", literal: "The eunuch Zhao Zhong's father died; he returned to bury him at Anping and usurpedly used a jade casket;", idiomatic: "The eunuch Zhao Zhong's father died. He returned to bury him at Anping and usurped the privilege of a jade casket;" },
  { zh: "穆下郡案驗，吏畏其嚴，遂發墓剖棺，陳屍出之。", literal: "Mu sent the commandery to investigate on the case; the clerks, fearing his severity, thereupon opened the tomb, cut open the coffin, and displayed the corpse outside.", idiomatic: "Mu sent the commandery to investigate. The clerks, fearing his severity, opened the tomb, cut open the coffin, and displayed the corpse outside." },
  { zh: "帝聞，大怒，征穆詣廷尉，輸作左校。", literal: "The Emperor heard of it and was greatly angry; he summoned Mu to the Minister of Justice and sent him to labor in the Left School.", idiomatic: "The Emperor heard of it and was greatly angry. He summoned Mu to the Minister of Justice and sent him to labor in the Left School." },
  { zh: "太學書生穎川劉陶等數千人詣闕上書訟穆曰：「伏見弛刑徒朱穆，處公憂國，拜州之日，志清奸惡。", literal: "Several thousand Imperial University students including Liu Tao of Yingchuan went to the palace gate to submit a petition on Mu's behalf, saying: \"Your servant has seen the released convict Zhu Mu, who in public office grieves for the state; on the day he took his province, his will was to purge treachery and evil.\"", idiomatic: "Several thousand Imperial University students including Liu Tao of Yingchuan went to the palace gate to submit a petition on Mu's behalf, saying, \"Your servant has seen the released convict Zhu Mu, who in public office grieves for the state. On the day he took his province, his will was to purge treachery and evil.\"" },
  { zh: "誠以常侍貴寵，父兄子弟布在州郡，競為虎狼，噬食小民，故穆張理天綱，補綴漏目，羅取殘禍，以塞天意。", literal: "\"Truly because the Regular Attendants are honored and favored, their fathers, brothers, sons, and younger brothers are spread through provinces and commanderies, competing as tigers and wolves to devour the common folk—therefore Mu spread heaven's net, mended the leaking mesh, gathered the remaining calamities, to block heaven's intent.\"", idiomatic: "\"Truly because the Regular Attendants are honored and favored, their fathers, brothers, sons, and younger brothers are spread through provinces and commanderies, competing as tigers and wolves to devour the common folk. Therefore Mu spread heaven's net, mended the leaking mesh, gathered the remaining calamities, and blocked heaven's intent.\"" },
  { zh: "由是內官鹹共恚疾，謗讟煩興，讒隙仍作，極其刑謫，輸作左校。", literal: "\"Thereby the inner officials were all together resentful; slander and vilification arose in profusion, slanderous breaches followed in succession, punishment was pushed to the extreme, and he was sent to labor in the Left School.\"", idiomatic: "\"Thereby the inner officials were all together resentful. Slander and vilification arose in profusion, slanderous breaches followed in succession, punishment was pushed to the extreme, and he was sent to labor in the Left School.\"" },
  { zh: "天下有識，皆以穆同勤禹、稷而被共、鯀之戾，若死者有知，則唐帝怒於崇山，重華忿於蒼墓矣！", literal: "\"All under heaven who had understanding held that Mu was diligent like Yu and Ji yet bore the guilt of Gun and Gong—if the dead had consciousness, then Tang Di would rage at Chong mountain and Chonghua would resent at the green tomb!\"", idiomatic: "\"All under heaven who had understanding held that Mu was diligent like Yu and Ji yet bore the guilt of Gun and Gong—if the dead had consciousness, then Tang Di would rage at Chong mountain and Chonghua would resent at the green tomb!\"" },
  { zh: "當今中官近習，竊持國柄，手握王爵，口銜天憲，運賞則使餓隸富於季孫，呼吸則令伊、顏化為桀、跖；", literal: "\"Now the inner officials and close favorites secretly hold the state's handles, grasp royal ranks in their hands, carry heaven's laws in their mouths—moving rewards makes starving slaves richer than Jisun, a breath turns Yi and Yan into Jie and Zhi;\"", idiomatic: "\"Now the inner officials and close favorites secretly hold the state's handles, grasp royal ranks in their hands, and carry heaven's laws in their mouths. Moving rewards makes starving slaves richer than Jisun, and a breath turns Yi and Yan into Jie and Zhi;\"" },
  { zh: "而穆獨亢然不顧身害，非惡榮而好辱，惡生而好死也，徒感王綱之不攝，懼天網之久失，故竭心懷憂，為上深計。", literal: "\"yet Mu alone stood upright and did not heed harm to his person—not because he hated glory and loved disgrace, hated life and loved death, but solely because he was moved that the royal cords were not gathered and feared the heaven's net had long been lost—therefore he exhausted his heart in grief and made deep plans for his lord.\"", idiomatic: "\"yet Mu alone stood upright and did not heed harm to his person—not because he hated glory and loved disgrace or hated life and loved death, but solely because he was moved that the royal cords were not gathered and feared heaven's net had long been lost. Therefore he exhausted his heart in grief and made deep plans for his lord.\"" },
  { zh: "臣願黥首系趾，代穆校作。", literal: "\"Your servant wishes to be tattooed on the head and bound at the ankle, to replace Mu in school labor.\"", idiomatic: "\"Your servant wishes to be tattooed on the head and bound at the ankle, to replace Mu in school labor.\"" },
  { zh: "」帝覽其奏，乃赦之。", literal: "\" The Emperor read their memorial and thereupon pardoned him.", idiomatic: "\" The Emperor read their memorial and thereupon pardoned him." },
  { zh: "冬，十月，太尉袁湯免，以太常胡廣為太尉。", literal: "In winter, the tenth month, Grand Commandant Yuan Tang was dismissed; Minister of Ceremonies Hu Guang was made Grand Commandant.", idiomatic: "In winter, in the tenth month, Grand Commandant Yuan Tang was dismissed, and Minister of Ceremonies Hu Guang was made Grand Commandant." },
  { zh: "司徒吳雄、司空趙戒免。", literal: "Minister over the Masses Wu Xiong and Minister of Works Zhao Jie were dismissed.", idiomatic: "Minister over the Masses Wu Xiong and Minister of Works Zhao Jie were dismissed." },
  { zh: "以太僕黃瓊為司徒，光祿勳房植為司空。", literal: "Chamberlain for the Imperial Stud Huang Qiong was made Minister over the Masses, and Household Counsellor Fang Zhi was made Minister of Works.", idiomatic: "Chamberlain for the Imperial Stud Huang Qiong was made Minister over the Masses, and Household Counsellor Fang Zhi was made Minister of Works." },
  { zh: "武陵蠻詹山等反，武陵太守汝南應奉招降之。", literal: "The Man of Wuling Zhan Shan and others rebelled; Administrator of Wuling Ying Feng of Runan induced them to surrender.", idiomatic: "The Man of Wuling Zhan Shan and others rebelled. Administrator of Wuling Ying Feng of Runan induced them to surrender." },
  { zh: "車師後部王阿羅多與戊部候嚴皓不相得，忿戾而反，攻圍屯田，殺傷吏士。", literal: "King Aluoduo of the Rear Division of Cheshi and the Wuji Colonel Yan Hao were incompatible; in angry defiance he rebelled, besieged the garrison colonies, and killed and wounded officials and soldiers.", idiomatic: "King Aluoduo of the Rear Division of Cheshi and the Wuji Colonel Yan Hao were incompatible. In angry defiance he rebelled, besieged the garrison colonies, and killed and wounded officials and soldiers." },
  { zh: "後部侯炭遮領餘民畔阿羅多，詣漢吏降。", literal: "Marquis Tanzhe of the Rear Division led the remnant people in defecting from Aluoduo and came to Han officials to surrender.", idiomatic: "Marquis Tanzhe of the Rear Division led the remnant people in defecting from Aluoduo and came to Han officials to surrender." },
  { zh: "阿羅多迫急，從百餘騎亡入北匈奴。", literal: "Aluoduo was pressed hard and fled with more than a hundred horsemen into the Northern Xiongnu.", idiomatic: "Aluoduo was pressed hard and fled with more than a hundred horsemen into the Northern Xiongnu." },
  { zh: "敦煌太守宋亮上立後部故王軍就質子卑君為王。", literal: "Administrator of Dunhuang Song Liang memorialized to establish Beijun, hostage son of the former king Junjiu of the Rear Division, as king.", idiomatic: "Administrator of Dunhuang Song Liang memorialized to establish Beijun, hostage son of the former king Junjiu of the Rear Division, as king." },
  { zh: "後阿羅多復從匈奴中還，與卑君爭國，頗收其國人。", literal: "Later Aluoduo again returned from among the Xiongnu and contested the state with Beijun, largely winning over his countrymen.", idiomatic: "Later Aluoduo again returned from among the Xiongnu and contested the state with Beijun, largely winning over his countrymen." },
  { zh: "戊校尉閻詳慮其招引北虜，將亂西域，乃開信告示，許復為王；", literal: "Colonel of the Wuji Yan Xiang feared he would draw in the northern barbarians and would disorder the Western Regions; he thereupon opened good faith and proclaimed, promising to restore him as king;", idiomatic: "Colonel of the Wuji Yan Xiang feared he would draw in the northern barbarians and disorder the Western Regions. He thereupon opened good faith and proclaimed, promising to restore him as king;" },
  { zh: "阿羅多及詣詳降。", literal: "Aluoduo thereupon came to Xiang and surrendered.", idiomatic: "Aluoduo thereupon came to Xiang and surrendered." },
  { zh: "於是更立阿羅多為王，將卑君還敦煌，以後部人三百帳與之。", literal: "Thereupon he was again established as king; Beijun was taken back to Dunhuang, and three hundred households of the rear people were given to him.", idiomatic: "Thereupon he was again established as king. Beijun was taken back to Dunhuang, and three hundred households of the rear people were given to him." },
  { zh: "春，正月，甲午，赦天下。", literal: "In spring, the first month, on jiawu day, amnesty was declared for all under heaven.", idiomatic: "In spring, in the first month, on jiawu day, amnesty was declared for all under heaven." },
  { zh: "二月，辛丑，復聽刺史、二千石行三年喪。", literal: "In the second month, on xinchou day, it was again permitted for Inspectors and the 2000-bushel officials to observe the three-year mourning.", idiomatic: "In the second month, on xinchou day, it was again permitted for Inspectors and the 2000-bushel officials to observe the three-year mourning." },
  { zh: "癸卯，京師地震。", literal: "On guimao day, the capital had an earthquake.", idiomatic: "On guimao day, the capital had an earthquake." },
  { zh: "夏，蝗。", literal: "In summer, locusts.", idiomatic: "In summer, there were locusts." },
  { zh: "東海朐山崩。", literal: "In Donghai, Mount Ju collapsed.", idiomatic: "In Donghai, Mount Ju collapsed." },
  { zh: "乙卯，封乳母馬惠子初為列候。", literal: "On yimao day, the wet nurse's son Ma Huizi Chu was enfeoffed as a full marquis.", idiomatic: "On yimao day, the wet nurse's son Ma Huizi Chu was enfeoffed as a full marquis." },
  { zh: "秋，九月，丁卯朔，日有食之。", literal: "In autumn, the ninth month, on the first day dingmao, there was a solar eclipse.", idiomatic: "In autumn, in the ninth month, on the first day dingmao, there was a solar eclipse." },
  { zh: "太尉胡廣免；", literal: "Grand Commandant Hu Guang was dismissed;", idiomatic: "Grand Commandant Hu Guang was dismissed;" },
  { zh: "以司徒黃瓊為太尉。", literal: "Minister over the Masses Huang Qiong was made Grand Commandant.", idiomatic: "Minister over the Masses Huang Qiong was made Grand Commandant." },
  { zh: "閏月，以光祿勳尹頌為司徒。", literal: "In the intercalary month, Household Counsellor Yin Song was made Minister over the Masses.", idiomatic: "In the intercalary month, Household Counsellor Yin Song was made Minister over the Masses." },
  { zh: "冬，十一月，甲辰，帝校獵上林苑，遂至函谷關。", literal: "In winter, the eleventh month, on jiachen day, the Emperor conducted a hunt in Shanglin Park and went on to Hangu Pass.", idiomatic: "In winter, in the eleventh month, on jiachen day, the Emperor conducted a hunt in Shanglin Park and went on to Hangu Pass." },
  { zh: "泰山、琅邪賊公孫舉、東郭竇等反，殺長吏。", literal: "In Taishan and Langye, the bandits Gongsun Ju, Dongguo Dou, and others rebelled and killed chief officials.", idiomatic: "In Taishan and Langye, the bandits Gongsun Ju, Dongguo Dou, and others rebelled and killed chief officials." },
  { zh: "春，正月，戊申，赦天下，改元。", literal: "In spring, the first month, on wushen day, amnesty was declared for all under heaven and the era name was changed.", idiomatic: "In spring, in the first month, on wushen day, amnesty was declared for all under heaven and the era name was changed." },
  { zh: "二月，司隸、冀州饑，人相食。", literal: "In the second month, in the Metropolitan Province and Jizhou there was famine; people ate one another.", idiomatic: "In the second month, in the Metropolitan Province and Jizhou there was famine, and people ate one another." },
  { zh: "太學生劉陶上疏陳事曰：「夫天之與帝，帝之與民，猶頭之與足，相須而行也。", literal: "Imperial University student Liu Tao submitted a memorial stating affairs, saying: \"Heaven and the Emperor, the Emperor and the people, are like head and foot—they must rely on one another to move.\"", idiomatic: "Imperial University student Liu Tao submitted a memorial stating affairs, saying, \"Heaven and the Emperor, the Emperor and the people, are like head and foot—they must rely on one another to move.\"" },
  { zh: "陛下目不視鳴條之事，耳不聞檀車之聲，天災不有痛於肌膚，震食不即損於聖體，故蔑三光之謬，輕上天之怒。", literal: "\"Your Majesty's eyes do not look on affairs at Mingtiao, your ears do not hear the sound of the prison cart; heavenly calamities do not pain your flesh, earthquakes and eclipses do not immediately harm your sacred person—therefore you despise the errors of the three luminaries and make light of heaven's anger.\"", idiomatic: "\"Your Majesty's eyes do not look on affairs at Mingtiao, and your ears do not hear the sound of the prison cart. Heavenly calamities do not pain your flesh, and earthquakes and eclipses do not immediately harm your sacred person—therefore you despise the errors of the three luminaries and make light of heaven's anger.\"" },
  { zh: "伏念高祖之起，始自布衣，合散扶傷，克成帝業，勤亦至矣；", literal: "\"Your servant considers that Gaozu's rise began from common cloth, gathered the scattered and tended the wounded, and overcame to complete the imperial enterprise—his diligence also reached the utmost;\"", idiomatic: "\"Your servant considers that Gaozu's rise began from common cloth, gathered the scattered and tended the wounded, and overcame to complete the imperial enterprise—his diligence also reached the utmost;\"" },
  { zh: "流福遺祚，至於陛下。", literal: "\"flowing blessing and bequeathed fortune down to Your Majesty.\"", idiomatic: "\"flowing blessing and bequeathed fortune down to Your Majesty.\"" },
  { zh: "陛下既不能增明烈考之軌，而忽高祖之勤，妄假利器，委授國柄，使群丑刑隸，芟刈小民，虎豹窟於鏖場，豺狼乳於春囿，貨殖者為窮冤之魂，貧餒者作饑寒之鬼，死者悲於窀穸，生者戚於朝野，是愚臣所為咨嗟長懷歎息者也！", literal: "\"Your Majesty is unable both to brighten and clarify your illustrious father's track and to heed Gaozu's diligence, rashly lends sharp instruments, entrusts the state's handle, lets a host of villains and convict slaves mow down the common folk—tigers and leopards den in the battleground, jackals and wolves suckle in the spring park, the money-making become souls of utter wrong, the poor and hungry become ghosts of famine and cold, the dead grieve in the grave mound, the living mourn in court and field—this is what your foolish servant sighs and long laments!\"", idiomatic: "\"Your Majesty is unable both to brighten your illustrious father's track and to heed Gaozu's diligence. You rashly lend sharp instruments and entrust the state's handle, letting a host of villains and convict slaves mow down the common folk. Tigers and leopards den in the battleground, jackals and wolves suckle in the spring park, the money-making become souls of utter wrong, the poor and hungry become ghosts of famine and cold, the dead grieve in the grave mound, and the living mourn in court and field—this is what your foolish servant sighs and long laments over!\"" },
  { zh: "且秦之將亡，正諫者誅，諛進者賞，嘉言結於忠舌，國命出於讒口，擅閻樂於咸陽，授趙高以車府，權去己而不知，威離身而不顧。", literal: "\"Moreover when Qin was about to perish, those who remonstrated uprightly were executed, flatterers who advanced were rewarded, fine words were tied on loyal tongues, the state's mandate came from slanderous mouths, Yan Yue was given free rein at Xianyang, Zhao Gao was entrusted with the carriage office—authority left oneself without knowing, majesty departed the person without heeding.\"", idiomatic: "\"Moreover when Qin was about to perish, those who remonstrated uprightly were executed and flatterers who advanced were rewarded. Fine words were tied on loyal tongues, and the state's mandate came from slanderous mouths. Yan Yue was given free rein at Xianyang, and Zhao Gao was entrusted with the carriage office—authority left oneself without knowing, and majesty departed the person without heeding.\"" },
  { zh: "古今一揆，成敗同勢，願陛下遠覽強秦之傾，近察哀、平之變，得失昭然，禍福可見。", literal: "\"Past and present are one measure, success and failure share the same momentum—your servant wishes Your Majesty to gaze far on strong Qin's fall, examine near the changes of Ai and Ping; gain and loss are bright, fortune and calamity can be seen.\"", idiomatic: "\"Past and present are one measure, and success and failure share the same momentum. Your servant wishes Your Majesty to gaze far on strong Qin's fall and examine near the changes of Ai and Ping—gain and loss are bright, and fortune and calamity can be seen.\"" },
  { zh: "臣又聞危非仁不扶，亂非智不救。", literal: "\"Your servant has also heard: peril is not supported without benevolence, disorder is not saved without wisdom.\"", idiomatic: "\"Your servant has also heard that peril is not supported without benevolence and disorder is not saved without wisdom.\"" },
  { zh: "竊見故冀州刺史南陽朱穆、前烏桓校尉臣同郡李膺，皆履正清平，貞高絕俗，斯實中興之良佐，國家之柱臣也，宜還本朝，挾輔王室。", literal: "\"Your servant has privately seen the former Inspector of Jizhou Zhu Mu of Nanyang and the former Colonel of the Wuhuan Li Ying of your servant's same commandery—both tread the upright and are clear and even, pure and lofty beyond the vulgar. These are truly fine assistants of the restoration and pillar ministers of the state; they should return to the central court and assist the royal house.\"", idiomatic: "\"Your servant has privately seen the former Inspector of Jizhou Zhu Mu of Nanyang and the former Colonel of the Wuhuan Li Ying of your servant's same commandery—both tread the upright and are clear and even, pure and lofty beyond the vulgar. These are truly fine assistants of the restoration and pillar ministers of the state. They should return to the central court and assist the royal house.\"" },
  { zh: "臣敢吐不時之義於諱言之朝，猶冰霜見日，必至消滅。", literal: "\"Your servant dares speak untimely righteousness in a court of tabooed words—like frost and ice meeting the sun, it must reach extinction.\"", idiomatic: "\"Your servant dares speak untimely righteousness in a court of tabooed words—like frost and ice meeting the sun, it must surely melt away.\"" },
  { zh: "臣始悲天下之可悲，今天下亦悲臣之愚惑也。", literal: "\"Your servant first grieved that all under heaven was lamentable; now all under heaven also grieves your servant's foolish delusion.\"", idiomatic: "\"Your servant first grieved that all under heaven was lamentable; now all under heaven also grieves your servant's foolish delusion.\"" },
  { zh: "」書奏，不省。", literal: "\" The memorial was submitted; the Emperor did not examine it.", idiomatic: "\" The memorial was submitted. The Emperor did not examine it." },
  { zh: "夏，南陽大水。", literal: "In summer, Nanyang had great flooding.", idiomatic: "In summer, Nanyang had great flooding." },
  { zh: "司空房植免；", literal: "Minister of Works Fang Zhi was dismissed;", idiomatic: "Minister of Works Fang Zhi was dismissed;" },
  { zh: "以太常韓縯為司空。", literal: "Minister of Ceremonies Han Yan was made Minister of Works.", idiomatic: "Minister of Ceremonies Han Yan was made Minister of Works." },
  { zh: "巴郡、益州郡山崩。", literal: "In Ba commandery and Yizhou commandery, mountains collapsed.", idiomatic: "In Ba commandery and Yizhou commandery, mountains collapsed." },
  { zh: "秋，南匈奴左薁鞬台耆、且渠伯德等反，寇美稷；", literal: "In autumn, Zuoguji Taiqi and Qiju Bode of the Southern Xiongnu and others rebelled and raided Meiji;", idiomatic: "In autumn, Zuoguji Taiqi and Qiju Bode of the Southern Xiongnu and others rebelled and raided Meiji;" },
  { zh: "東羌復舉種應之。", literal: "the Eastern Qiang again rose by tribes in response.", idiomatic: "The Eastern Qiang again rose by tribes in response." },
  { zh: "安定屬國都尉敦煌張奐初到職，壁中唯有二百許人，聞之，即勒兵而出；", literal: "Zhang Huan of Dunhuang, Commandant of the Dependent State of Anding, had just taken office; in the fortress there were only about two hundred men. Hearing of it, he immediately mustered troops and went out;", idiomatic: "Zhang Huan of Dunhuang, Commandant of the Dependent State of Anding, had just taken office. In the fortress there were only about two hundred men. Hearing of it, he immediately mustered troops and went out;" },
  { zh: "軍吏以為力不敵，叩頭爭止之。", literal: "the army officers thought their strength could not match the enemy and kowtowed in contention to stop him.", idiomatic: "The army officers thought their strength could not match the enemy and kowtowed in contention to stop him." },
  { zh: "奐不聽，遂進屯長城，收集兵士，遣將王衛招誘東羌，因據龜茲縣，使南匈奴不得交通。", literal: "Huan would not listen; he thereupon advanced and encamped at the Long Walls, gathered soldiers, sent the general Wang Wei to induce the Eastern Qiang, and thereby held Guizi county so the Southern Xiongnu could not communicate.", idiomatic: "Huan would not listen. He thereupon advanced and encamped at the Long Walls, gathered soldiers, sent the general Wang Wei to induce the Eastern Qiang, and thereby held Guizi county so the Southern Xiongnu could not communicate." },
  { zh: "東羌諸豪遂相率與奐共擊薁鞬等，破之。", literal: "The great chiefs of the Eastern Qiang thereupon joined one another to attack Zuoguji and others together with Huan and defeated them.", idiomatic: "The great chiefs of the Eastern Qiang thereupon joined one another to attack Zuoguji and others together with Huan and defeated them." },
  { zh: "伯德惶恐，將其眾降，郡界以寧。", literal: "Bode was fearful and led his host in surrender; the commandery borders were thereby pacified.", idiomatic: "Bode was fearful and led his host in surrender. The commandery borders were thereby pacified." },
  { zh: "羌豪遺奐馬二十匹，金鐻八枚。", literal: "Qiang chiefs sent Huan twenty horses and eight gold tokens.", idiomatic: "Qiang chiefs sent Huan twenty horses and eight gold tokens." },
  { zh: "奐於諸羌前以酒酹地曰：「使馬如羊，不以入廄；", literal: "Before all the Qiang, Huan poured wine on the ground, saying: \"Even if horses were like sheep, I would not put them in the stable;\"", idiomatic: "Before all the Qiang, Huan poured wine on the ground, saying, \"Even if horses were like sheep, I would not put them in the stable;\"" },
  { zh: "使金如粟，不以入懷。", literal: "\"even if gold were like grain, I would not put it in my bosom.\"", idiomatic: "\"even if gold were like grain, I would not put it in my bosom.\"" },
  { zh: "」悉以還之。", literal: "\" He returned them all.", idiomatic: "\" He returned them all." },
  { zh: "前此八都尉率好財貨，為羌所患苦；", literal: "Before this, eight colonels in succession had loved goods and wealth and were a hardship to the Qiang;", idiomatic: "Before this, eight colonels in succession had loved goods and wealth and were a hardship to the Qiang;" },
  { zh: "及奐正身潔己，無不悅服，威化大行。", literal: "when Huan was upright in person and pure toward himself, none failed to be pleased and submit; authority and transformation spread greatly.", idiomatic: "When Huan was upright in person and pure toward himself, none failed to be pleased and submit, and authority and transformation spread greatly." },
  { zh: "春，三月，蜀郡屬國夷反。", literal: "In spring, the third month, the Yi of the dependent state of Shu commandery rebelled.", idiomatic: "In spring, in the third month, the Yi of the dependent state of Shu commandery rebelled." },
  { zh: "初，鮮卑檀石槐，勇健有智略，部落畏服，乃施法禁，平曲直，無敢犯者，遂推以為大人。", literal: "Initially, Tanshihuai of the Xianbei was brave, strong, and had strategy; the tribes feared and obeyed him. He thereupon applied legal prohibitions, settled right and wrong, and none dared violate them—therefore they pushed him as great chief.", idiomatic: "Initially, Tanshihuai of the Xianbei was brave, strong, and had strategy, and the tribes feared and obeyed him. He thereupon applied legal prohibitions and settled right and wrong, and none dared violate them—therefore they pushed him as great chief." },
  { zh: "檀石槐立庭於彈汙山、歠仇水上，去高柳北三百餘里，兵馬甚盛；", literal: "Tanshihuai established his court on Mount Danwu and by the waters of Shuchou, more than three hundred li north of Gaoliu; his troops and horses were very strong;", idiomatic: "Tanshihuai established his court on Mount Danwu and by the waters of Shuchou, more than three hundred li north of Gaoliu. His troops and horses were very strong;" },
  { zh: "東、西部大人皆歸焉。", literal: "the great chiefs of the eastern and western divisions all submitted to him.", idiomatic: "The great chiefs of the eastern and western divisions all submitted to him." },
  { zh: "因南抄緣邊，北拒丁零，東卻夫餘，西擊烏孫，盡據匈奴故地，東西萬四千餘里。", literal: "He thereby raided south along the border, repelled north the Dingling, drove back east Fuyu, attacked west the Wusun, and fully held the Xiongnu's former lands—fourteen thousand and more li east to west.", idiomatic: "He thereby raided south along the border, repelled the Dingling in the north, drove back Fuyu in the east, and attacked the Wusun in the west, fully holding the Xiongnu's former lands—fourteen thousand and more li east to west." },
  { zh: "秋，七月，檀石槐寇雲中。", literal: "In autumn, the seventh month, Tanshihuai raided Yunzhong.", idiomatic: "In autumn, in the seventh month, Tanshihuai raided Yunzhong." },
  { zh: "以故烏桓校尉李膺為度遼將軍。", literal: "The former Colonel of the Wuhuan Li Ying was made General Who Crosses the Liao.", idiomatic: "The former Colonel of the Wuhuan Li Ying was made General Who Crosses the Liao." },
  { zh: "膺到邊，羌、胡皆望風畏服，先所掠男女，悉詣塞下送還之。", literal: "When Ying reached the border, Qiang and Hu all saw the wind and feared and submitted; men and women previously carried off all came to below the passes and returned them.", idiomatic: "When Ying reached the border, Qiang and Hu all saw the wind and feared and submitted. Men and women previously carried off all came below the passes and were returned." },
  { zh: "公孫舉、東郭竇等聚眾至三萬人，寇青、兗、徐三州，破壞郡縣。", literal: "Gongsun Ju, Dongguo Dou, and others gathered a host to thirty thousand men, raided the three provinces Qing, Yan, and Xu, and destroyed commanderies and counties.", idiomatic: "Gongsun Ju, Dongguo Dou, and others gathered a host of thirty thousand men, raided the three provinces Qing, Yan, and Xu, and destroyed commanderies and counties." },
  { zh: "連年討之，不能克。", literal: "For successive years they were attacked but could not be overcome.", idiomatic: "For successive years they were attacked but could not be overcome." },
  { zh: "尚書選能治劇者，以司徒掾穎川韓韶為嬴長。", literal: "The Masters of Writing selected one able to handle severe cases and appointed Clerk of the Minister over the Masses Han Shao of Yingchuan as Magistrate of Ying.", idiomatic: "The Masters of Writing selected one able to handle severe cases and appointed Clerk of the Minister over the Masses Han Shao of Yingchuan as Magistrate of Ying." },
  { zh: "賊聞其賢，相戒不入嬴境。", literal: "The bandits heard of his worth and warned one another not to enter Ying territory.", idiomatic: "The bandits heard of his worth and warned one another not to enter Ying territory." },
  { zh: "餘縣流民萬餘戶入縣界，韶開倉賑之，主者爭謂不可。", literal: "More than ten thousand households of displaced people from other counties entered the county borders; Shao opened the granaries to relieve them, and those in charge contended that it could not be done.", idiomatic: "More than ten thousand households of displaced people from other counties entered the county borders. Shao opened the granaries to relieve them, and those in charge contended that it could not be done." },
  { zh: "韶曰：「長活溝壑之人，而以此伏罪，含笑入地矣。", literal: "Shao said: \"To long preserve people in ditches and gullies, yet on this account submit to punishment—I would enter the earth with a smile.", idiomatic: "Shao said, \"To long preserve people in ditches and gullies, yet on this account submit to punishment—I would enter the earth with a smile." },
  { zh: "」太守素知韶名德，竟無所坐。", literal: "\" The Administrator had long known Shao's reputation and virtue and in the end imposed no punishment.", idiomatic: "\" The Administrator had long known Shao's reputation and virtue and in the end imposed no punishment." },
  { zh: "韶與同郡荀淑、鐘皓、陳寔皆嘗為縣長，所至以德政稱，時人謂之「穎川四長」。", literal: "Shao together with Xun Shu, Zhong Hao, and Chen Shi of the same commandery had all at one time been county magistrates; wherever they went they were famed for virtuous government, and men of the time called them \"the Four Chiefs of Yingchuan.\"", idiomatic: "Shao together with Xun Shu, Zhong Hao, and Chen Shi of the same commandery had all at one time been county magistrates. Wherever they went they were famed for virtuous government, and men of the time called them \"the Four Chiefs of Yingchuan.\"" },
  { zh: "初，鮮卑寇遼東，屬國都尉武威段熲率所領馳赴之。", literal: "Initially, the Xianbei raided Liaodong; Commandant of the Dependent State Duan Jiong of Wuwei led those under his command to gallop to the rescue.", idiomatic: "Initially, the Xianbei raided Liaodong. Commandant of the Dependent State Duan Jiong of Wuwei led those under his command to gallop to the rescue." },
  { zh: "既而恐賊驚去，乃使驛騎詐繼璽書召熲，熲於道偽退，潛於還路設伏；", literal: "Before long, fearing the bandits would be startled and flee, he sent a post rider with a forged follow-on imperial-seal letter summoning Jiong; Jiong on the road feigned retreat and secretly set an ambush on the return route;", idiomatic: "Before long, fearing the bandits would be startled and flee, he sent a post rider with a forged follow-on imperial-seal letter summoning Jiong. Jiong on the road feigned retreat and secretly set an ambush on the return route;" },
  { zh: "虜以為信然，乃入追熲，熲因大縱兵，悉斬獲之。", literal: "the barbarians believed it was genuine and thereupon entered in pursuit of Jiong; Jiong thereby unleashed his troops greatly and beheaded and captured them all.", idiomatic: "The barbarians believed it was genuine and thereupon entered in pursuit of Jiong. Jiong thereby unleashed his troops greatly and beheaded and captured them all." },
  { zh: "坐詐為璽書，當伏重刑；", literal: "For counterfeiting the imperial-seal letter, he should have suffered severe punishment;", idiomatic: "For counterfeiting the imperial-seal letter, he should have suffered severe punishment;" },
  { zh: "以有功，論司寇；", literal: "because he had merit, he was sentenced as minister of crime;", idiomatic: "because he had merit, he was sentenced as minister of crime;" },
  { zh: "刑竟，拜議郎。", literal: "when the punishment was complete, he was appointed Consultant.", idiomatic: "When the punishment was complete, he was appointed Consultant." },
  { zh: "至是，詔以東方盜賊昌熾，令公卿選將帥有文武材者。", literal: "At this time, an edict because bandits in the east blazed fiercely ordered the dukes and ministers to select commanders with civil and military talent.", idiomatic: "At this time, because bandits in the east blazed fiercely, an edict ordered the dukes and ministers to select commanders with civil and military talent." },
  { zh: "司徒尹頌薦熲，拜中郎將，擊舉、竇等，大破斬之，獲首萬餘級，餘黨降散。", literal: "Minister over the Masses Yin Song recommended Jiong; he was appointed Colonel of the Gentlemen, attacked Ju, Dou, and others, routed and beheaded them greatly, obtained heads numbering more than ten thousand, and the remnant faction surrendered and scattered.", idiomatic: "Minister over the Masses Yin Song recommended Jiong. He was appointed Colonel of the Gentlemen, attacked Ju, Dou, and others, routed and beheaded them greatly, obtained more than ten thousand heads, and the remnant faction surrendered and scattered." },
  { zh: "封熲為列侯。", literal: "Jiong was enfeoffed as a full marquis.", idiomatic: "Jiong was enfeoffed as a full marquis." },
  { zh: "冬，十二月，京師地震。", literal: "In winter, the twelfth month, the capital had an earthquake.", idiomatic: "In winter, in the twelfth month, the capital had an earthquake." },
  { zh: "封梁不疑子馬為穎陰侯，梁胤子桃為城父侯。", literal: "Liang Buyi's son Ma was enfeoffed as Marquis of Yingyin, and Liang Yin's son Tao was enfeoffed as Marquis of Chengfu.", idiomatic: "Liang Buyi's son Ma was enfeoffed as Marquis of Yingyin, and Liang Yin's son Tao was enfeoffed as Marquis of Chengfu." },
  { zh: "category:資治通鑑", literal: "—", idiomatic: "—" }
];
